class Blocked(RuntimeError):
    pass


def require(ok, reason):
    if not ok:
        raise Blocked(reason)


def sha(raw):
    return hashlib.sha256(raw).hexdigest().upper()


def stable(obj):
    return json.dumps(obj, sort_keys=True, separators=(",", ":"), ensure_ascii=True,
                      allow_nan=False).encode("utf-8")


def json_bytes(obj):
    return stable(obj) + b"\n"


def parse(raw):
    def pairs(items):
        out = {}
        for key, value in items:
            require(key not in out, "JSON_DUPLICATE_KEY:" + key)
            out[key] = value
        return out
    def nonfinite(value):
        raise Blocked("JSON_NONFINITE:" + value)
    try:
        return json.loads(raw, object_pairs_hook=pairs, parse_constant=nonfinite)
    except (ValueError, UnicodeError) as exc:
        raise Blocked("JSON_INVALID") from exc


def digest(value):
    require(isinstance(value, str) and re.fullmatch(r"[0-9A-F]{64}", value), "SHA256_INVALID")
    return value


def basename(name):
    require(isinstance(name, str) and re.fullmatch(r"[A-Za-z0-9_@.-]+", name)
            and name not in (".", "..") and not name.endswith((".", " ")),
            "BASENAME_INVALID")
    require(name.split(".")[0].upper() not in {"CON", "PRN", "AUX", "NUL", *("COM"+str(i) for i in range(1,10)), *("LPT"+str(i) for i in range(1,10))}, "DEVICE_NAME")
    return name



def safe_stop_event_name(value):
    require(isinstance(value,str) and SAFE_STOP_EVENT_PATTERN.fullmatch(value) is not None,
            "SAFE_STOP_EVENT_NAME_INVALID")
    return value


class NamedStopEvent:
    """Read-only watcher for an orchestrator-owned manual-reset Win32 event."""
    SYNCHRONIZE=0x00100000
    WAIT_OBJECT_0=0
    WAIT_TIMEOUT=258

    def __init__(self,name,on_signal):
        require(os.name=="nt","SAFE_STOP_EVENT_WINDOWS_REQUIRED")
        self.name=safe_stop_event_name(name)
        self.on_signal=on_signal
        self.k=ctypes.WinDLL("kernel32",use_last_error=True)
        self.k.OpenEventW.argtypes=[U32,BOOL,w.LPCWSTR]
        self.k.OpenEventW.restype=HANDLE
        self.k.WaitForSingleObject.argtypes=[HANDLE,U32]
        self.k.WaitForSingleObject.restype=U32
        self.k.CloseHandle.argtypes=[HANDLE]
        self.k.CloseHandle.restype=BOOL
        self.handle=self.k.OpenEventW(self.SYNCHRONIZE,False,self.name)
        require(bool(self.handle),"SAFE_STOP_EVENT_NOT_FOUND")
        self.closed=False
        self.thread=None

    def start(self):
        require(self.thread is None,"SAFE_STOP_EVENT_ALREADY_STARTED")
        def watch():
            while not self.closed:
                result=self.k.WaitForSingleObject(self.handle,250)
                if result==self.WAIT_OBJECT_0:
                    self.on_signal()
                    return
                require(result==self.WAIT_TIMEOUT,"SAFE_STOP_EVENT_WAIT_FAILED")
        self.thread=threading.Thread(target=watch,name="tickstore-safe-stop-event",daemon=True)
        self.thread.start()

    def close(self):
        self.closed=True
        if self.thread is not None:
            self.thread.join(timeout=1.0)
            self.thread=None
        if self.handle:
            self.k.CloseHandle(self.handle)
            self.handle=None


def relative_path(value):
    require(isinstance(value, str) and "\\" not in value and ":" not in value, "RELATIVE_PATH_INVALID")
    parts=value.split("/")
    for part in parts:
        basename(part)
    return parts


def norm(path):
    return os.path.normcase(os.path.abspath(str(path))).rstrip("\\/")


def path_component(value):
    require(value not in ("", ".", "..") and not any(c in value for c in '\\/:<>"|?*')
            and not value.endswith(("."," ")), "PATH_COMPONENT_INVALID")


def vss_shadow_volume_root(path):
    """Return the VSS device-object root or None for an ordinary filesystem path."""
    p=PureWindowsPath(str(path))
    parts=p.parts
    if len(parts) < 3:
        return None
    if p.anchor.casefold() != "\\\\?\\GLOBALROOT\\".casefold():
        return None
    if parts[1].casefold() != "device":
        return None
    if re.fullmatch(r"HarddiskVolumeShadowCopy[0-9]+",parts[2],re.IGNORECASE) is None:
        return None
    return PureWindowsPath(p.anchor,parts[1],parts[2])


def protected_parent_is_real(target,parent):
    """VSS GLOBALROOT/Device are object-manager pseudo-ancestors, not volume directories."""
    floor=vss_shadow_volume_root(target)
    if floor is None:
        return True
    pp=PureWindowsPath(str(parent))
    fp=PureWindowsPath(str(floor))
    pparts=tuple(x.casefold() for x in pp.parts)
    fparts=tuple(x.casefold() for x in fp.parts)
    return len(pparts) >= len(fparts) and pparts[:len(fparts)] == fparts


def vss_directory_open_path(path,directory):
    """Use a trailing backslash only when opening the VSS device-object root as a directory."""
    text=str(path)
    if not directory:
        return text
    floor=vss_shadow_volume_root(path)
    if floor is None:
        return text
    if norm(PureWindowsPath(text)) != norm(floor):
        return text
    return text.rstrip("\\/") + "\\"


def final_path_query_flags(path):
    """VSS shadow device objects are not Mount Manager DOS volumes; query their NT name."""
    return 0x2 if vss_shadow_volume_root(path) is not None else 0x0


def comparable_final_path(path,final):
    expected=norm(path)
    if vss_shadow_volume_root(path) is not None:
        prefix="\\\\?\\GLOBALROOT"
        require(str(path).upper().startswith(prefix.upper()),"VSS_FINAL_EXPECTED_PREFIX")
        expected_nt=norm(str(path)[len(prefix):])
        return expected_nt,norm(final)
    comparable=final[4:] if final.startswith("\\\\?\\") and not final.startswith("\\\\?\\GLOBALROOT\\") else final
    return expected,norm(comparable)


_core = None


def frozen_core():
    """Execute authenticated embedded bytes, never project files from sys.path."""
    global _core
    if _core is None:
        import builtins
        modules = {}
        trusted_import = builtins.__import__
        def embedded_import(name, *args, **kwargs):
            if name == "pts2g_reference":
                return modules[name]
            return trusted_import(name, *args, **kwargs)
        for name, encoded, expected in (("pts2g_reference", REFERENCE_B64, REFERENCE_SHA),
                                        ("tickstore_serial_runner", CORE_B64, CORE_SHA)):
            raw=base64.b64decode(encoded, validate=True)
            require(sha(raw)==expected, "EMBEDDED_CORE_HASH_MISMATCH:"+name)
            module=types.ModuleType(name)
            module.__file__="<authenticated-embedded-"+name+">"
            module.__dict__["__builtins__"]={**vars(builtins), "__import__":embedded_import}
            exec(compile(raw, module.__file__, "exec"), module.__dict__)
            modules[name]=module
        _core=modules["tickstore_serial_runner"]
    return _core


# Native structures use Windows ABI widths, including on test hosts.
U32=ctypes.c_uint32
U64=ctypes.c_uint64
BOOL=ctypes.c_int32
HANDLE=ctypes.c_void_p
NTSTATUS=ctypes.c_int32
STATUS_PENDING=0x00000103
FILE_FLAG_OVERLAPPED=0x40000000
_unresolved_native_renames=[]  # Own all kernel-visible storage until completion is proved.


class RENAME_OPTIONS(ctypes.Union):
    _fields_=[("ReplaceIfExists",ctypes.c_ubyte),("Flags",U32)]


class FILE_RENAME_INFORMATION(ctypes.Structure):
    _anonymous_=("Options",)
    _fields_=[("Options",RENAME_OPTIONS),("RootDirectory",HANDLE),
              ("FileNameLength",U32),("FileName",ctypes.c_wchar*1)]


class IO_STATUS_UNION(ctypes.Union):
    _fields_=[("Status",NTSTATUS),("Pointer",HANDLE)]


class IO_STATUS_BLOCK(ctypes.Structure):
    _anonymous_=("Result",)
    _fields_=[("Result",IO_STATUS_UNION),("Information",ctypes.c_size_t)]


def native_rename_abi():
    require(ctypes.sizeof(HANDLE)==8 and ctypes.sizeof(ctypes.c_wchar)==2,"NATIVE_RENAME_WIN64_ABI")
    require(ctypes.sizeof(NTSTATUS)==4 and NTSTATUS(-1).value<0,"NATIVE_RENAME_NTSTATUS_SIGNED32")
    require(ctypes.sizeof(FILE_RENAME_INFORMATION)==24 and
            FILE_RENAME_INFORMATION.RootDirectory.offset==8 and
            FILE_RENAME_INFORMATION.FileNameLength.offset==16 and
            FILE_RENAME_INFORMATION.FileName.offset==20,"NATIVE_RENAME_INFORMATION_ABI")
    require(ctypes.sizeof(IO_STATUS_BLOCK)==16 and IO_STATUS_BLOCK.Status.offset==0 and
            IO_STATUS_BLOCK.Information.offset==8,"NATIVE_RENAME_IOSB_ABI")
    return {"pointer":8,"wchar":2,"ntstatus_signed_bits":32,"rename_size":24,
            "root_offset":8,"length_offset":16,"name_offset":20,"iosb_size":16,"information_offset":8}


def classify_native_rename(status):
    value=NTSTATUS(status).value & 0xffffffff
    if value==STATUS_PENDING:
        return "PENDING_UNEXPECTED"
    if value==0:
        return "COMPLETE_SUCCESS"
    if value==0xc0000035:
        return "COMPLETE_COLLISION"
    return "COMPLETE_FAILURE"  # Includes unrecognized informational/warning statuses.


class NativeRenameOperation:
    def __init__(self,source,directory,name,deadline):
        self.source,self.directory,self.name=source,directory,name
        self.before,self.directory_before=source.info(),directory.info()
        self.before_hash=source.hash()
        raw=name.encode("utf-16-le")
        self.buffer=ctypes.create_string_buffer(ctypes.sizeof(FILE_RENAME_INFORMATION)+len(raw))
        self.info=FILE_RENAME_INFORMATION.from_buffer(self.buffer)
        self.info.ReplaceIfExists=0
        self.info.RootDirectory=directory.handle
        self.info.FileNameLength=len(raw)
        ctypes.memmove(ctypes.addressof(self.buffer)+FILE_RENAME_INFORMATION.FileName.offset,raw,len(raw))
        self.iosb=IO_STATUS_BLOCK();self.iosb.Status=STATUS_PENDING
        self.deadline=deadline;self.completed=False;self.completion_observed=False
        self.record={"source_path":str(source.path),"destination_path":str(directory.path/name),
            "root_directory":hex(directory.handle),"basename":name,"replace_if_exists":False,
            "buffer_bytes":len(self.buffer),"file_name_length":len(raw),"source_before":self.before,
            "source_hash_before":self.before_hash,"directory_before":self.directory_before,
            "completion":"PENDING_UNEXPECTED","requires_physical_classification":False}


class FILE_ID_INFO(ctypes.Structure):
    _fields_=[("VolumeSerialNumber",U64),("FileId",ctypes.c_ubyte*16)]


class FILE_STANDARD_INFO(ctypes.Structure):
    _fields_=[("AllocationSize",ctypes.c_int64),("EndOfFile",ctypes.c_int64),
              ("NumberOfLinks",U32),("DeletePending",ctypes.c_ubyte),("Directory",ctypes.c_ubyte)]


class FILE_ATTRIBUTE_TAG_INFO(ctypes.Structure):
    _fields_=[("FileAttributes",U32),("ReparseTag",U32)]


class FILE_RENAME_INFO(ctypes.Structure):
    _fields_=[("Flags",U32),("RootDirectory",HANDLE),("FileNameLength",U32),("FileName",ctypes.c_wchar*1)]


class ProtectedFile:
    def __init__(self, store, path, handle, parents, directory=False, writable=False):
        self.store,self.path,self.handle,self.parents=store,Path(path),handle,parents
        self.directory,self.writable=directory,writable
        self.open_flags=None;self._rename_inflight=None
        self.identity=self.info()

    def _no_inflight_rename(self):
        require(self._rename_inflight is None,"NATIVE_RENAME_PENDING_RESOURCE_IN_USE")

    def info(self):
        self._no_inflight_rename()
        k=self.store.k
        fid,standard,tag=FILE_ID_INFO(),FILE_STANDARD_INFO(),FILE_ATTRIBUTE_TAG_INFO()
        for kind,obj in ((18,fid),(1,standard),(9,tag)):
            self.store.check(k.GetFileInformationByHandleEx(self.handle,kind,ctypes.byref(obj),ctypes.sizeof(obj)),"FILE_INFORMATION")
        require(not(tag.FileAttributes & 0x400) and tag.ReparseTag==0,"REPARSE_REJECTED")
        require(bool(standard.Directory)==self.directory,"OBJECT_TYPE_MISMATCH")
        require(not standard.DeletePending,"DELETE_PENDING")
        if not self.directory:
            require(standard.NumberOfLinks==1,"HARDLINK_REJECTED")
        buf=ctypes.create_unicode_buffer(32768)
        flags=final_path_query_flags(self.path)
        size=k.GetFinalPathNameByHandleW(self.handle,buf,len(buf),flags)
        if not (0<size<len(buf)):
            err=ctypes.get_last_error()
            raise Blocked("FINAL_PATH_FAILED:FLAGS="+hex(flags)+":WINERROR="+str(err))
        final=buf.value
        expected,comparable=comparable_final_path(self.path,final)
        require(comparable==expected,"FINAL_PATH_MISMATCH")
        return {"volume":int(fid.VolumeSerialNumber),"file_id":bytes(fid.FileId).hex().upper(),
                "bytes":int(standard.EndOfFile),"links":int(standard.NumberOfLinks),"path":norm(self.path)}

    def seek(self, offset=0):
        self._no_inflight_rename()
        self.store.check(self.store.k.SetFilePointerEx(self.handle,offset,None,0),"SEEK")

    def chunks(self, size=1024*1024):
        self.seek()
        buf=ctypes.create_string_buffer(size)
        while True:
            count=U32()
            self.store.check(self.store.k.ReadFile(self.handle,buf,size,ctypes.byref(count),None),"READ")
            if not count.value:
                break
            yield buf.raw[:count.value]

    def read(self, limit=64*1024*1024):
        require(self.info()["bytes"]<=limit,"METADATA_TOO_LARGE")
        return b"".join(self.chunks())

    def hash(self):
        before=self.info(); h=hashlib.sha256()
        for chunk in self.chunks():
            h.update(chunk)
        require(self.info()==before,"HANDLE_CHANGED_DURING_HASH")
        return h.hexdigest().upper(),before["bytes"]

    def write(self, data):
        self._no_inflight_rename()
        require(self.writable,"READ_ONLY_HANDLE")
        for offset in range(0,len(data),1024*1024):
            chunk=data[offset:offset+1024*1024];count=U32()
            self.store.check(self.store.k.WriteFile(self.handle,chunk,len(chunk),ctypes.byref(count),None),"WRITE")
            require(count.value==len(chunk),"SHORT_WRITE")

    def flush(self):
        self._no_inflight_rename()
        self.store.check(self.store.k.FlushFileBuffers(self.handle),"FLUSH")

    def rename(self, directory, name):
        return self.store.rename_relative(self,directory,basename(name))

    def delete_lock(self):
        self._no_inflight_rename()
        require(self.path.name=="TICKSTORE_WRITER.lock","DELETE_ONLY_WRITER_LOCK")
        disposition=ctypes.c_ubyte(1)
        self.store.check(self.store.k.SetFileInformationByHandle(self.handle,4,ctypes.byref(disposition),1),"LOCK_DISPOSITION")

    def close(self):
        self._no_inflight_rename()
        if self.handle is not None:
            self.store.check(self.store.k.CloseHandle(self.handle),"CLOSE")
            self.handle=None
        while self.parents:
            self.parents[-1].close()
            self.parents.pop()

    def __enter__(self):
        return self

    def __exit__(self, typ, value, tb):
        try:
            self.close()
        except BaseException:
            if typ is None:
                raise


class Win32Store:
    """Protected same-handle I/O; this layer never opens historical CSV content."""
    def __init__(self):
        require(os.name=="nt","WINDOWS_REQUIRED")
        self.rename_abi=native_rename_abi()
        self.rename_deadline_seconds=900.0  # Existing metadata bootstrap ceiling; never a retry budget.
        self.rename_events=[];self.rename_blocked=False
        self.k=ctypes.WinDLL("kernel32",use_last_error=True)
        try:
            self.nt=ctypes.WinDLL("ntdll.dll",use_last_error=True,winmode=0x800)
            self.nt.NtSetInformationFile.restype=NTSTATUS
            self.nt.NtSetInformationFile.argtypes=[HANDLE,ctypes.POINTER(IO_STATUS_BLOCK),HANDLE,U32,ctypes.c_int32]
            self.nt.RtlNtStatusToDosError.restype=U32
            self.nt.RtlNtStatusToDosError.argtypes=[NTSTATUS]
        except (AttributeError,OSError) as exc:
            raise Blocked("NATIVE_RENAME_EXPORT_UNAVAILABLE") from exc
        signatures={
            "CreateFileW":(HANDLE,[w.LPCWSTR,U32,U32,HANDLE,U32,U32,HANDLE]),
            "CloseHandle":(BOOL,[HANDLE]),
            "GetFileInformationByHandleEx":(BOOL,[HANDLE,ctypes.c_int,HANDLE,U32]),
            "GetFinalPathNameByHandleW":(U32,[HANDLE,w.LPWSTR,U32,U32]),
            "SetFileInformationByHandle":(BOOL,[HANDLE,ctypes.c_int,HANDLE,U32]),
            "SetFilePointerEx":(BOOL,[HANDLE,ctypes.c_int64,HANDLE,U32]),
            "ReadFile":(BOOL,[HANDLE,HANDLE,U32,ctypes.POINTER(U32),HANDLE]),
            "WriteFile":(BOOL,[HANDLE,HANDLE,U32,ctypes.POINTER(U32),HANDLE]),
            "FlushFileBuffers":(BOOL,[HANDLE]),
            "WaitForSingleObject":(U32,[HANDLE,U32]),
        }
        for name,(ret,args) in signatures.items():
            fn=getattr(self.k,name);fn.restype=ret;fn.argtypes=args

    @staticmethod
    def check(ok,label):
        if not ok:
            raise Blocked(label+":WINERROR="+str(ctypes.get_last_error()))

    def _status_evidence(self,status):
        value=NTSTATUS(status).value
        # Translation is diagnostic only. Never let its failure change completion authority.
        try:
            mapped=int(self.nt.RtlNtStatusToDosError(value))
        except Exception:
            mapped=None
        return {"signed":value,"unsigned":value & 0xffffffff,"hex":f"0x{value & 0xffffffff:08X}",
                "mapped_win32":mapped}

    def _complete_rename(self,op,status):
        require(op.completion_observed,"NATIVE_RENAME_COMPLETION_NOT_PROVED")
        completion=classify_native_rename(status)
        require(completion!="PENDING_UNEXPECTED","NATIVE_RENAME_STILL_PENDING")
        op.completed=True
        op.source._rename_inflight=op.directory._rename_inflight=None
        _unresolved_native_renames.remove(op)
        op.record.update(completion=completion,final_status=self._status_evidence(status),
                         io_status_block_status=self._status_evidence(op.iosb.Status),
                         io_status_block_information=int(op.iosb.Information))
        if completion=="COMPLETE_SUCCESS":
            op.source.path=op.directory.path/op.name
        after=op.source.info();directory_after=op.directory.info()
        require(all(after[key]==op.before[key] for key in ("volume","file_id","bytes")),"RENAME_IDENTITY_CHANGED")
        require(op.source.hash()==op.before_hash,"RENAME_BYTES_CHANGED")
        require(directory_after==op.directory_before,"RENAME_DIRECTORY_IDENTITY_CHANGED")
        op.record.update(source_after=after,source_hash_after=op.source.hash(),directory_after=directory_after)
        op.record["post_identity_verified"]=True
        return completion

    def resolve_pending_rename(self,op):
        """No second rename is submitted. A late completion never clears the sticky BLOCK."""
        require(op in _unresolved_native_renames and op.source.store is self,"NATIVE_RENAME_PENDING_NOT_OWNED")
        while True:
            remaining=op.deadline-time.monotonic()
            if remaining<=0:
                raise Blocked("NATIVE_RENAME_PENDING_DEADLINE:PHYSICAL_STATE_CLASSIFICATION_REQUIRED")
            wait=int(self.k.WaitForSingleObject(op.source.handle,max(1,min(1000,int(remaining*1000)))))
            if wait==0:
                # Own the only I/O on this source. Do not use an unobserved IOSB as authority.
                final=NTSTATUS(op.iosb.Status).value
                if final!=STATUS_PENDING:
                    op.completion_observed=True
                    return self._complete_rename(op,final)
                raise Blocked("NATIVE_RENAME_SIGNAL_WITHOUT_COMPLETION:PHYSICAL_STATE_CLASSIFICATION_REQUIRED")
            require(wait==258,"NATIVE_RENAME_PENDING_WAIT_FAILED:PHYSICAL_STATE_CLASSIFICATION_REQUIRED")

    def rename_relative(self,source,directory,name):
        require(not self.rename_blocked,"NATIVE_RENAME_BLOCKED_PHYSICAL_CLASSIFICATION_REQUIRED")
        source._no_inflight_rename();directory._no_inflight_rename()
        require(source.handle is not None and source.writable and not source.directory,"NATIVE_RENAME_DELETE_HANDLE_REQUIRED")
        require(directory.handle is not None and directory.directory,"NATIVE_RENAME_PIN_REQUIRED")
        require(source.open_flags is not None and not source.open_flags & FILE_FLAG_OVERLAPPED,"NATIVE_RENAME_SYNCHRONOUS_HANDLE_REQUIRED")
        require(source.info()["volume"]==directory.info()["volume"],"CROSS_VOLUME_RENAME")
        require(self.rename_deadline_seconds>0,"NATIVE_RENAME_DEADLINE_REQUIRED")
        op=NativeRenameOperation(source,directory,basename(name),time.monotonic()+self.rename_deadline_seconds)
        source._rename_inflight=directory._rename_inflight=op
        _unresolved_native_renames.append(op);self.rename_events.append(op.record)
        try:
            status=NTSTATUS(self.nt.NtSetInformationFile(source.handle,ctypes.byref(op.iosb),op.buffer,len(op.buffer),10)).value
            op.record["return_status"]=self._status_evidence(status)
            op.record["initial_completion"]=classify_native_rename(status)
            if status==STATUS_PENDING:
                completion=self.resolve_pending_rename(op)
            else:
                op.completion_observed=True
                completion=self._complete_rename(op,status)
            if completion!="COMPLETE_SUCCESS":
                raise Blocked("RENAME_NO_OVERWRITE:"+completion+":NTSTATUS="+op.record["final_status"]["hex"])
            return dict(op.record)
        except BaseException:
            if not op.completed:
                self.rename_blocked=True
                op.record["requires_physical_classification"]=True
            elif not op.record.get("post_identity_verified"):
                self.rename_blocked=True  # Identity/hash check failed after a completed physical rename.
                op.record["requires_physical_classification"]=True
            raise

    def _open(self,path,directory=False,new=False,mutate=False,parents=None):
        path=Path(path)
        require(path.suffix.lower()!=".csv","CSV_ACCESS_FORBIDDEN")
        require(path.is_absolute(),"ABSOLUTE_PATH_REQUIRED")
        for part in path.parts[1:]:
            path_component(part)
        access=(0x001000a1 if directory else 0x80000000)
        if mutate:
            access|=0x40000000|0x00010000
        flags=0x00200000 | (0x02000000 if directory else 0) | (0x80000000 if new else 0)
        require(not flags & FILE_FLAG_OVERLAPPED,"NATIVE_RENAME_SYNCHRONOUS_HANDLE_REQUIRED")
        open_path=vss_directory_open_path(path,directory)
        handle=self.k.CreateFileW(open_path,access,3 if directory else (0 if mutate else 1),None,1 if new else 3,flags,None)
        self.check(handle != ctypes.c_void_p(-1).value,"CREATE_NEW" if new else "OPEN_PROTECTED")
        try:
            result=ProtectedFile(self,path,handle,parents or [],directory,mutate)
            result.open_flags=flags
            return result
        except BaseException:
            self.k.CloseHandle(handle)
            raise

    def open(self,path,*,directory=False,new=False,mutate=False):
        path=Path(os.path.abspath(path));parents=[]
        try:
            for parent in reversed(path.parents):
                if not protected_parent_is_real(path,parent):
                    continue
                parents.append(self._open(parent,directory=True))
            return self._open(path,directory,new,mutate,parents)
        except BaseException:
            for parent in reversed(parents):
                parent.close()
            raise

    def exists(self,path):
        try:
            os.lstat(path)
            return True
        except FileNotFoundError:
            return False

    def inventory(self,root):
        """A live inventory is only a hint; closure calls this on a VSS generation."""
        root=Path(root);out=[]
        def walk(directory):
            with self.open(directory,directory=True):
                for entry in sorted(os.scandir(directory),key=lambda e:e.name):
                    st=entry.stat(follow_symlinks=False)
                    require(not(getattr(st,"st_file_attributes",0)&0x400),"INVENTORY_REPARSE")
                    if entry.is_dir(follow_symlinks=False):
                        walk(Path(entry.path))
                    else:
                        with self.open(entry.path) as f:
                            h,n=f.hash()
                            out.append({"path":Path(entry.path).relative_to(root).as_posix(),"sha256":h,"bytes":n})
        walk(root)
        return out

    def immutable(self,directory,name,raw):
        basename(name)
        with self.open(directory,directory=True) as parent:
            with self.open(Path(directory)/name,new=True,mutate=True) as f:
                f.write(raw);f.flush()
                require(f.hash()==(sha(raw),len(raw)),"IMMUTABLE_WRITE_MISMATCH")
                return dict(f.info())


class Watchdog:
    def __init__(self,now,deadline,liveness=45.0):
        require(deadline>0 and liveness>0,"DEADLINE_UNCALIBRATED")
        self.start=self.last_heartbeat=self.last_progress=now
        self.deadline,self.liveness=deadline,liveness
        self.counters={}

    def observe(self,now,counters):
        require(now>=self.last_heartbeat,"CLOCK_REGRESSION")
        require(set(counters)>=set(self.counters),"PROGRESS_COUNTER_DISAPPEARED")
        changed=False
        for key,value in counters.items():
            require(type(value) is int and value>=self.counters.get(key,0),"PROGRESS_REGRESSION")
            changed|=value>self.counters.get(key,0)
        self.last_heartbeat=now
        if changed:
            self.last_progress=now
        self.counters=dict(counters)

    def check(self,now,alive=True,io_error=False):
        require(alive and now-self.last_heartbeat<=self.liveness,"LIVENESS_LOST")
        require(not io_error,"IO_ERROR")
        require(now-self.start<=self.deadline,"CALIBRATED_OPERATION_DEADLINE")
        return "NO_PROGRESS_DIAGNOSTIC" if now-self.last_progress>=180 else "HEALTHY"


def watchdog_process_fatal(label):
    """Fail-closed when a supervised operation exceeds a fatal watchdog contract.

    Continuing after a stuck publisher I/O thread would violate the single-writer
    transaction model.  Abrupt process termination is intentional: the root Job
    kills descendants and the durable state is reclassified on the next bootstrap.
    """
    text="WATCHDOG_FATAL="+str(label)
    try:
        print(text,flush=True)
    finally:
        if os.name=="nt":
            k=ctypes.WinDLL("kernel32",use_last_error=True)
            k.GetCurrentProcess.restype=HANDLE
            k.TerminateProcess.argtypes=[HANDLE,U32]
            k.TerminateProcess(k.GetCurrentProcess(),86)
        os._exit(86)


def monitored_operation(label,deadline,liveness,heartbeat_seconds,operation,progress=lambda:{},fatal=None):
    """Run blocking I/O in a daemon thread while the supervisor enforces hard time.

    Heartbeat is supervisor liveness and is intentionally independent of progress.
    Progress counters come from the operation.  180 s no-progress is diagnostic only.
    """
    require(deadline>0 and liveness>0 and heartbeat_seconds>0,"MONITORED_OPERATION_CONTRACT")
    box={};done=threading.Event();lock=threading.Lock();state={"counters":{}}
    def update(values):
        require(isinstance(values,dict),"MONITORED_PROGRESS_OBJECT")
        with lock:
            state["counters"]={str(k):int(v) for k,v in values.items()}
    def run():
        try:
            box["result"]=operation(update)
        except BaseException as exc:
            box["error"]=exc
        finally:
            done.set()
    thread=threading.Thread(target=run,name="tickstore-watch-"+re.sub(r"[^A-Za-z0-9_.-]","_",label)[:40],daemon=True)
    start=time.monotonic();watch=Watchdog(start,float(deadline),float(liveness));thread.start()
    diagnostics=[];next_heartbeat=start
    fatal=fatal or watchdog_process_fatal
    while not done.wait(min(1.0,float(heartbeat_seconds))):
        now=time.monotonic()
        if now>=next_heartbeat:
            with lock:counters=dict(state["counters"])
            watch.observe(now,counters);next_heartbeat=now+float(heartbeat_seconds)
        try:
            diagnostic=watch.check(now,alive=thread.is_alive())
        except Blocked as exc:
            fatal(label+":"+str(exc))
            raise Blocked(label+":"+str(exc))
        if diagnostic=="NO_PROGRESS_DIAGNOSTIC" and not diagnostics:
            diagnostics.append({"operation":label,"diagnostic":diagnostic,"elapsed_seconds":now-start})
    thread.join()
    if "error" in box:
        raise box["error"]
    now=time.monotonic()
    with lock:counters=dict(state["counters"])
    watch.observe(now,counters);watch.check(now,alive=True)
    return box.get("result"),diagnostics


class RecoveryProcessLease:
    """Machine-global single-supervisor lease used as the recovery process census authority."""
    def __init__(self,name=PROCESS_CENSUS_MUTEX):
        require(os.name=="nt","PROCESS_CENSUS_WINDOWS_REQUIRED")
        self.k=ctypes.WinDLL("kernel32",use_last_error=True)
        self.k.CreateMutexW.restype=HANDLE
        self.k.CreateMutexW.argtypes=[HANDLE,BOOL,w.LPCWSTR]
        self.k.CloseHandle.argtypes=[HANDLE]
        self.handle=self.k.CreateMutexW(None,False,name)
        Win32Store.check(bool(self.handle),"PROCESS_CENSUS_MUTEX_CREATE")
        if ctypes.get_last_error()==183:
            self.k.CloseHandle(self.handle);self.handle=None
            raise Blocked("RECOVERY_PROCESS_CENSUS_LIVE_SUPERVISOR")

    def close(self):
        if self.handle:
            Win32Store.check(self.k.CloseHandle(self.handle),"PROCESS_CENSUS_MUTEX_CLOSE")
            self.handle=None

    def __enter__(self):
        return self

    def __exit__(self,*exc):
        self.close()


def size_class(byte_count):
    require(type(byte_count) is int and byte_count>0,"SIZE_CLASS_BYTES")
    limits=(64,128,256,512,1024,2048,4096)
    mib=1024*1024
    for index,limit in enumerate(limits):
        if byte_count<=limit*mib:
            return "B"+str(index)
    return "B7"


def deadline_contract(gate,members):
    """Return frozen deadlines. Canary uses preregistered bootstrap values; production uses calibrated profile."""
    if gate.get("production_recovery_authorized") is True:
        require("DEADLINE_PROFILE.json" in members,"DEADLINE_PROFILE_REQUIRED")
        profile=parse(members["DEADLINE_PROFILE.json"])
        require(profile.get("schema")=="DEADLINE_PROFILE_V004","DEADLINE_PROFILE_SCHEMA")
        required={"heartbeat_target_seconds","liveness_fatal_seconds","no_progress_diagnostic_seconds",
                  "metadata_hard_deadline_seconds","cooperative_shutdown_ceiling_seconds",
                  "terminate_wait_seconds","kill_wait_seconds","streaming_by_size_class"}
        require(set(profile)==required|{"schema"},"DEADLINE_PROFILE_FIELDS")
        by_class=profile["streaming_by_size_class"]
        require(set(by_class)=={"B0","B1","B2","B3","B4","B5","B6","B7"},"DEADLINE_SIZE_CLASSES")
        require(all(type(by_class[k]) in (int,float) and by_class[k]>=900 for k in by_class),"DEADLINE_CLASS_UNCALIBRATED")
    else:
        profile=gate.get("bootstrap_deadlines")
        require(isinstance(profile,dict),"CANARY_BOOTSTRAP_DEADLINES_REQUIRED")
        expected={"heartbeat_target_seconds":5,"liveness_fatal_seconds":45,"streaming_hard_deadline_seconds":7200,
                  "metadata_hard_deadline_seconds":900,"cooperative_shutdown_ceiling_seconds":900,
                  "terminate_wait_seconds":120,"kill_wait_seconds":60,"no_progress_diagnostic_seconds":180}
        require(profile==expected,"CANARY_BOOTSTRAP_DEADLINES_DIVERGENT")
        profile={**profile,"streaming_by_size_class":{f"B{i}":7200 for i in range(8)}}
    require(profile["heartbeat_target_seconds"]>0 and profile["heartbeat_target_seconds"]<profile["liveness_fatal_seconds"],"HEARTBEAT_LIVENESS_CONTRACT")
    require(profile["no_progress_diagnostic_seconds"]==180,"NO_PROGRESS_DIAGNOSTIC_CONTRACT")
    return profile


def prep_worker_main(address,auth_handle,worker_id,heartbeat_seconds):
    """Authenticated descendant worker. Executable bytes arrive on stdin from the admitted supervisor."""
    require(os.name=="nt","PREP_WORKER_WINDOWS_REQUIRED")
    require(sys.version_info[:3]==(3,14,7) and sys.flags.isolated and sys.flags.no_site,"PREP_WORKER_RUNTIME_CONTRACT")
    require(os.getpid() in job_members(),"PREP_WORKER_NOT_IN_ROOT_JOB")
    from multiprocessing.connection import Client
    import msvcrt
    fd=msvcrt.open_osfhandle(int(auth_handle),os.O_RDONLY|os.O_BINARY)
    with os.fdopen(fd,"rb") as auth_stream:
        auth=auth_stream.read(33)
    require(len(auth)==32,"PREP_AUTH_KEY_LENGTH")
    conn=Client(address,family="AF_PIPE",authkey=auth)
    created=process_creation_time(os.getpid())
    conn.send({"type":"hello","worker_id":worker_id,"pid":os.getpid(),"process_creation_time":created})
    from compression import zstd
    store=Win32Store()
    try:
        while True:
            message=conn.recv()
            op=message.get("op")
            if op=="STOP":
                conn.send({"type":"stopped","worker_id":worker_id,"pid":os.getpid()})
                return 0
            require(op=="PREP","PREP_WORKER_OPERATION")
            required={"op","task_id","nonce","task_sha256","scratch_root","entry","contract","month"}
            require(set(message)==required,"PREP_WORKER_TASK_FIELDS")
            body={k:message[k] for k in required-{"task_sha256"}}
            require(sha(stable(body))==message["task_sha256"],"PREP_WORKER_TASK_DIGEST")
            box={};done=threading.Event()
            def execute():
                try:
                    box["result"]=prep(store,Path(message["scratch_root"]),message["entry"],message["contract"],message["month"],zstd)
                except BaseException as exc:
                    box["error"]={"type":type(exc).__name__,"message":str(exc)}
                finally:
                    done.set()
            thread=threading.Thread(target=execute,name="tickstore-prep-"+message["task_id"],daemon=True)
            thread.start();sequence=0
            while not done.wait(float(heartbeat_seconds)):
                sequence+=1
                conn.send({"type":"heartbeat","worker_id":worker_id,"pid":os.getpid(),"process_creation_time":created,
                           "task_id":message["task_id"],"nonce":message["nonce"],"sequence":sequence})
            thread.join()
            if "error" in box:
                conn.send({"type":"error","worker_id":worker_id,"pid":os.getpid(),"process_creation_time":created,
                           "task_id":message["task_id"],"nonce":message["nonce"],"error":box["error"]})
            else:
                conn.send({"type":"result","worker_id":worker_id,"pid":os.getpid(),"process_creation_time":created,
                           "task_id":message["task_id"],"nonce":message["nonce"],"task_sha256":message["task_sha256"],
                           "result":box["result"]})
    finally:
        conn.close()


class PrepSupervisor:
    """Up to 22 authenticated descendant PREP workers; no worker can publish canonical bytes."""
    def __init__(self,source_bytes,scratch_root,days,months,s0,profile,workers,stop_requested=lambda:False):
        require(os.name=="nt","PREP_SUPERVISOR_WINDOWS_REQUIRED")
        require(isinstance(source_bytes,(bytes,bytearray)) and source_bytes,"PREP_SOURCE_BYTES_REQUIRED")
        require(type(workers) is int and 1<=workers<=MAX_PREP_WORKERS,"PREP_WORKER_COUNT")
        self.source_bytes=bytes(source_bytes);self.scratch_root=str(scratch_root);self.days=days;self.months=months;self.s0=s0
        self.profile=profile;self.worker_count=min(workers,len(s0["days"]));self.stop_requested=stop_requested
        self.listener=None;self.processes={};self.connections={};self.diagnostics=[]
        self.launch_job_members=set(job_members());self.owned_process_identities={}
        require(os.getpid() in self.launch_job_members,"PREP_SUPERVISOR_NOT_IN_JOB")

    def _launch(self):
        from multiprocessing.connection import Listener
        import msvcrt
        auth=os.urandom(32);address=r"\\.\pipe\tickstore-prep-"+uuid.uuid4().hex
        self.listener=Listener(address=address,family="AF_PIPE",authkey=auth)
        accept_box=[];accept_error=[];ready=threading.Event()
        def acceptor():
            try:
                for _ in range(self.worker_count):
                    accept_box.append(self.listener.accept())
            except BaseException as exc:
                accept_error.append(exc)
            finally:
                ready.set()
        threading.Thread(target=acceptor,name="tickstore-prep-accept",daemon=True).start()
        flags=int(getattr(subprocess,"CREATE_NO_WINDOW",0))
        for index in range(self.worker_count):
            wid=f"W{index+1:02d}"
            read_fd,write_fd=os.pipe();read_handle=msvcrt.get_osfhandle(read_fd);os.set_handle_inheritable(read_handle,True)
            startup=subprocess.STARTUPINFO();startup.lpAttributeList={"handle_list":[read_handle]}
            cmd=[sys.executable,"-I","-S","-B","-","--prep-worker","--prep-pipe",address,"--prep-auth-handle",str(read_handle),
                 "--prep-worker-id",wid,"--prep-heartbeat",str(self.profile["heartbeat_target_seconds"])]
            try:
                proc=subprocess.Popen(cmd,stdin=subprocess.PIPE,stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL,
                                      creationflags=flags,startupinfo=startup,close_fds=True)
            finally:
                os.close(read_fd)
            try:
                os.write(write_fd,auth)
            finally:
                os.close(write_fd)
            self.processes[wid]=proc
            proc.stdin.write(self.source_bytes);proc.stdin.close()
        require(ready.wait(30),"PREP_WORKER_CONNECT_TIMEOUT")
        if accept_error:
            raise Blocked("PREP_WORKER_ACCEPT:"+str(accept_error[0]))
        require(len(accept_box)==self.worker_count,"PREP_WORKER_CONNECT_COUNT")
        hellos={}
        deadline=time.monotonic()+30
        for conn in accept_box:
            remaining=max(0.1,deadline-time.monotonic())
            require(conn.poll(remaining),"PREP_WORKER_HELLO_TIMEOUT")
            hello=conn.recv();require(hello.get("type")=="hello","PREP_WORKER_HELLO")
            wid=hello.get("worker_id");require(wid in self.processes and wid not in hellos,"PREP_WORKER_ID")
            proc=self.processes[wid]
            require(hello.get("pid")==proc.pid,"PREP_WORKER_PID")
            creation=hello.get("process_creation_time")
            require(creation==process_creation_time(proc.pid),"PREP_WORKER_PROCESS_IDENTITY")
            require(proc.pid in job_members(),"PREP_WORKER_JOB_MEMBERSHIP")
            self.owned_process_identities[wid]={"pid":proc.pid,"process_creation_time":creation}
            self.connections[wid]=conn;hellos[wid]=hello
        require(set(hellos)==set(self.processes),"PREP_WORKER_HELLO_SET")

    def _task(self,key):
        contract=self.days[key];entry=self.s0["days"][key];month=self.months[contract["month_id"]]
        body={"op":"PREP","task_id":"prep-"+key,"nonce":uuid.uuid4().hex,"scratch_root":self.scratch_root,
              "entry":entry,"contract":contract,"month":month}
        return {**body,"task_sha256":sha(stable(body))}

    def run(self):
        if self.worker_count==0:return {}
        from multiprocessing.connection import wait
        self._launch();pending=list(sorted(self.s0["days"]));active={};results={};completed=0;primary_error=None
        try:
            def assign(wid):
                if not pending:return False
                key=pending.pop(0);message=self._task(key);self.connections[wid].send(message)
                deadline=self.profile["streaming_by_size_class"][size_class(int(message["entry"]["partial"]["bytes"]))]
                watch=Watchdog(time.monotonic(),deadline,self.profile["liveness_fatal_seconds"])
                active[wid]={"key":key,"message":message,"watch":watch,"last_sequence":0}
                return True
            for wid in sorted(self.connections):assign(wid)
            while active:
                if self.stop_requested():
                    raise KeyboardInterrupt()
                mapping={conn:wid for wid,conn in self.connections.items() if wid in active}
                ready=wait(list(mapping),timeout=1.0) if mapping else []
                now=time.monotonic()
                for conn in ready:
                    wid=mapping[conn];state=active[wid];message=conn.recv();proc=self.processes[wid]
                    require(message.get("worker_id")==wid and message.get("pid")==proc.pid,"PREP_RESPONSE_IDENTITY")
                    require(message.get("process_creation_time")==process_creation_time(proc.pid),"PREP_RESPONSE_PROCESS_IDENTITY")
                    require(message.get("task_id")==state["message"]["task_id"] and message.get("nonce")==state["message"]["nonce"],"PREP_RESPONSE_TASK_IDENTITY")
                    if message.get("type")=="heartbeat":
                        require(type(message.get("sequence")) is int and message["sequence"]>state["last_sequence"],"PREP_HEARTBEAT_SEQUENCE")
                        state["last_sequence"]=message["sequence"];state["watch"].observe(now,{"completed":0})
                    elif message.get("type")=="error":
                        raise Blocked("PREP_WORKER_ERROR:"+json.dumps(message.get("error"),sort_keys=True))
                    elif message.get("type")=="result":
                        require(message.get("task_sha256")==state["message"]["task_sha256"],"PREP_RESPONSE_TASK_DIGEST")
                        state["watch"].observe(now,{"completed":1});state["watch"].check(now,alive=(proc.poll() is None))
                        result=message["result"];require(result.get("date_key")==state["key"],"PREP_RESPONSE_DATE")
                        results[state["key"]]=result;completed+=1;del active[wid];assign(wid)
                    else:
                        raise Blocked("PREP_WORKER_RESPONSE_TYPE")
                now=time.monotonic()
                for wid,state in list(active.items()):
                    alive=self.processes[wid].poll() is None
                    diag=state["watch"].check(now,alive=alive)
                    if diag=="NO_PROGRESS_DIAGNOSTIC":
                        self.diagnostics.append({"worker_id":wid,"date_key":state["key"],"diagnostic":diag,"elapsed":now-state["watch"].start})
            require(len(results)==len(self.s0["days"]),"PREP_RESULT_COUNT")
            return results
        except BaseException as exc:
            primary_error=exc
            raise
        finally:
            try:
                self.close()
            except BaseException as cleanup_error:
                if primary_error is None:
                    raise
                try:primary_error.add_note("PREP_CLEANUP_ERROR:"+repr(cleanup_error))
                except Exception:pass

    def close(self):
        for wid,conn in list(self.connections.items()):
            try:
                if self.processes.get(wid) is not None and self.processes[wid].poll() is None:
                    conn.send({"op":"STOP"})
            except Exception:
                pass
        deadline=time.monotonic()+float(self.profile["terminate_wait_seconds"])
        for proc in self.processes.values():
            remaining=max(0.0,deadline-time.monotonic())
            try:proc.wait(timeout=remaining)
            except subprocess.TimeoutExpired:proc.terminate()
        kill_deadline=time.monotonic()+float(self.profile["kill_wait_seconds"])
        for proc in self.processes.values():
            if proc.poll() is None:
                remaining=max(0.0,kill_deadline-time.monotonic())
                try:proc.wait(timeout=remaining)
                except subprocess.TimeoutExpired:proc.kill();proc.wait(timeout=5)
        for proc in self.processes.values():
            require(proc.poll() is not None,"PREP_PROCESS_STILL_RUNNING")
            if os.name=="nt":
                handle=getattr(proc,"_handle",None)
                require(handle is not None and hasattr(handle,"Close"),"PREP_PROCESS_HANDLE_UNAVAILABLE")
                handle.Close()
        for conn in self.connections.values():
            try:conn.close()
            except Exception:pass
        if self.listener is not None:
            try:self.listener.close()
            except Exception:pass
        self.connections.clear();self.processes.clear();self.listener=None
        final_members=set(job_members());residual=[]
        for wid,identity in sorted(self.owned_process_identities.items()):
            pid=int(identity["pid"]);created=int(identity["process_creation_time"])
            if pid not in final_members:
                continue
            current=process_creation_time(pid)
            if current==created:
                residual.append({"worker_id":wid,"pid":pid,"process_creation_time":created})
        self.diagnostics.append({"event":"PREP_JOB_CLEANUP","launch_job_members":sorted(self.launch_job_members),
                                 "final_job_members":sorted(final_members),"owned_workers":len(self.owned_process_identities),
                                 "owned_residuals":residual})
        require(not residual,"PREP_RESIDUAL_OWNED_PROCESSES:"+json.dumps(residual,sort_keys=True))



def classify_day(container,commit,record):
    table={(False,False,False):"PENDING",(True,False,False):"CONTAINER_ONLY",
           (True,True,False):"CONTAINER_COMMIT",(True,True,True):"TERMINAL"}
    state=table.get((bool(container),bool(commit),bool(record)))
    require(state is not None,"INVALID_PHYSICAL_DAY_STATE")
    return state


def classify_set(states,c0):
    require(all(states[key]=="TERMINAL" for key in c0),"C0_NOT_TERMINAL")
    require(sum(value in ("CONTAINER_ONLY","CONTAINER_COMMIT") for value in states.values())<=1,
            "MULTIPLE_PARTIAL_S0_DAYS")


def manifest_bytes(records,updated_unix_ns):
    require(type(updated_unix_ns) is int and updated_unix_ns>=0,"MANIFEST_TIMESTAMP_AUTHORITY_REQUIRED")
    require(all(key==value["date_key"] for key,value in records.items()),"MANIFEST_DATE_KEY")
    return json_bytes({"schema":MANIFEST_SCHEMA,"records":records,"updated_unix_ns":updated_unix_ns})


def rederive_manifest(raw,records):
    obj=parse(raw)
    require(set(obj)=={"schema","records","updated_unix_ns"} and obj["schema"]==MANIFEST_SCHEMA,
            "MANIFEST_SCHEMA_FIELDS")
    expected=manifest_bytes(records,obj["updated_unix_ns"])
    require(raw==expected,"MANIFEST_REDERIVATION_MISMATCH")
    return expected


def manifest_candidate(candidates,expected):
    matches=[item for item in candidates if item[1]==expected]
    require(len(matches)==1,"MANIFEST_ABSENT_CANDIDATES:"+str(len(matches)))
    return matches[0][0]


def generation_equal(a,b):
    keys={"snapshot_id","snapshot_set_id","provider_id","device_object","volume_identity"}
    return all(key in a and key in b and a[key]==b[key] for key in keys)


def safe_stop_decision(canonical,s0):
    bad=("missing","divergent","duplicate_date","orphan_journal","orphan_partial",
         "unexpected_grammar","reparse","hardlink")
    good=(canonical.get("pass") is True and s0.get("pass") is True
          and generation_equal(canonical.get("generation",{}),s0.get("generation",{}))
          and all(type(s0.get(key)) is int and s0[key]==S0_COUNT
                  for key in ("required_s0","journals","partials","cert_match"))
          and all(type(s0.get(key)) is int and s0[key]==0 for key in bad))
    return "YES" if good else "NO"


def s0_inventory_gate(certificate,observed,generation):
    """observed objects are gathered from one shadow root, never supplied by a disk hint."""
    expected=certificate["days"]
    counters=dict.fromkeys(("missing","divergent","duplicate_date","orphan_journal","orphan_partial",
                           "unexpected_grammar","reparse","hardlink"),0)
    out={"required_s0":len(expected),"journals":0,"partials":0,"cert_match":0,
         "generation":generation,"pass":False}
    entries={};ordered=[];allowed=set()
    for key,record in sorted(expected.items()):
        for kind in ("journal","partial"):
            allowed.add(record[kind]["path"])
        entries[key]={"journal":[],"partial":[]}
    for obj in observed:
        key,kind=obj["date_key"],obj["kind"]
        require(kind in ("journal","partial"),"S0_OBJECT_KIND")
        if obj["path"] not in allowed:
            counters["unexpected_grammar"]+=1
        counters["reparse"]+=int(bool(obj.get("reparse")))
        counters["hardlink"]+=int(obj.get("links")!=1)
        if key in entries:
            entries[key][kind].append(obj)
    for key,kinds in sorted(entries.items()):
        js,ps=kinds["journal"],kinds["partial"]
        out["journals"]+=len(js);out["partials"]+=len(ps)
        counters["duplicate_date"]+=int(len(js)>1 or len(ps)>1)
        counters["missing"]+=int(not js)+int(not ps)
        counters["orphan_journal"]+=len(js) if not ps else 0
        counters["orphan_partial"]+=len(ps) if not js else 0
        if len(js)!=1 or len(ps)!=1:
            continue
        exp=expected[key]
        ok=all(all(obj.get(field)==exp[kind][field] for field in ("path","sha256","bytes"))
               and obj.get("namespace")==exp["namespace"]
               for kind,obj in (("journal",js[0]),("partial",ps[0])))
        ok=ok and js[0].get("contract")==exp["contract"]
        counters["divergent"]+=int(not ok)
        out["cert_match"]+=int(ok)
        ordered.append({"date_key":key,"namespace":exp["namespace"],
                        "journal":{f:js[0].get(f) for f in ("path","sha256","bytes")},
                        "partial":{f:ps[0].get(f) for f in ("path","sha256","bytes")}})
    out.update(counters)
    out["inventory_sha256"]=sha(stable(ordered))
    out["pass"]=(len(expected)==S0_COUNT and out["cert_match"]==S0_COUNT and
                 out["journals"]==out["partials"]==S0_COUNT and not any(counters.values()))
    return out


def promotion_gate(final,promotion):
    require(final["pass"] is True and promotion["pass"] is True,"PROMOTION_AUDIT_FAILED")
    require(final["generation"]["snapshot_id"]!=promotion["generation"]["snapshot_id"],"PROMOTION_REQUIRES_FRESH_GENERATION")
    require(final["inventory"]==promotion["inventory"] and final["manifest_sha256"]==promotion["manifest_sha256"],
            "POST_FULL_LIVE_EQ_FINAL_GENERATION_GATE_BLOCKED")
    return {"gate":"POST_FULL_LIVE_EQ_FINAL_GENERATION_GATE","pass":True,
            "promotion_generation":promotion["generation"]}


def ledger_from_bytes(raw):
    import csv  # Only the authenticated ledger's CSV tables; never historical source CSV.
    require(sha(raw)==LEDGER_SHA,"LEDGER_SHA_MISMATCH")
    with zipfile.ZipFile(io.BytesIO(raw)) as archive:
        require(archive.testzip() is None,"LEDGER_CRC")
        days=list(csv.DictReader(io.StringIO(archive.read("P4A_ALL_DAYS.csv").decode("utf-8-sig"))))
        months=list(csv.DictReader(io.StringIO(archive.read("P4A_MONTHS.csv").decode("utf-8-sig"))))
    require(len(days)==TOTAL_DAYS and len({d["date_key"] for d in days})==TOTAL_DAYS,"LEDGER_DATES")
    require(sum(int(d["rows"]) for d in days)==TOTAL_ROWS,"LEDGER_ROWS")
    require(len(months)==75 and len({m["month_id"] for m in months})==75,"LEDGER_MONTHS")
    require([d["date_key"] for d in days]==sorted(d["date_key"] for d in days),"LEDGER_ORDER")
    return {d["date_key"]:d for d in days},{m["month_id"]:m for m in months}


def day_paths(root,contract):
    key=contract["date_key"];month=contract["month_id"]
    require(re.fullmatch(r"\d{8}",key) and re.fullmatch(r"\d{4}_\d{2}",month),"CONTRACT_PATH_GRAMMAR")
    directory=Path(root)/"WIN@N"/month
    return directory/key, directory/(key+".pts2g"), directory/(key+".commit.json")


def oracle_contract(oracle,contract,month):
    core=frozen_core()
    require(isinstance(oracle,dict),"ORACLE_OBJECT")
    rebuilt=core.make_oracle(contract,month,oracle.get("source_identity"),LEDGER_SHA,oracle.get("runner_ids"))
    require(oracle==rebuilt,"ORACLE_LEDGER_CONTRACT")
    require(oracle["runner_ids"]["runner_sha256"]==CORE_SHA,"ORACLE_FROZEN_RC1_PROVENANCE")
    require(oracle["runner_ids"]["reference_sha256"]==REFERENCE_SHA,"ORACLE_REFERENCE_PROVENANCE")
    identity=oracle["source_identity"]
    require(identity["sha256"]==month["source_sha256"].upper() and identity["size"]==int(month["source_size"]),"ORACLE_SOURCE_SEAL")
    return oracle


def prep(store,scratch_root,entry,contract,month,zstd):
    core=frozen_core()
    paths={kind:Path(scratch_root).joinpath(*relative_path(entry[kind]["path"])) for kind in ("journal","partial")}
    with contextlib.ExitStack() as stack:
        journal=stack.enter_context(store.open(paths["journal"]))
        partial=stack.enter_context(store.open(paths["partial"]))
        j=parse(journal.read());oracle=oracle_contract(j.get("oracle"),contract,month)
        core.validate_validated_partial(paths["partial"],paths["journal"],contract,oracle,zstd,
                                        allowed_states=("VALIDATED_PENDING_PUBLISH",))
        evidence={}
        for kind,obj in (("journal",journal),("partial",partial)):
            h,n=obj.hash()
            require((h,n)==(entry[kind]["sha256"],entry[kind]["bytes"]),"PREP_CERTIFICATE_BYTES:"+kind)
            evidence[kind]={"path":entry[kind]["path"],"sha256":h,"bytes":n,"identity":obj.info()}
        require(entry["contract"]==oracle,"PREP_CERTIFICATE_CONTRACT")
        return {"date_key":contract["date_key"],"oracle":oracle,"evidence":evidence,
                "container_sha256":evidence["partial"]["sha256"],"container_bytes":evidence["partial"]["bytes"]}


def validate_pair(store,root,contract,oracle,zstd):
    core=frozen_core();_,cp,kp=day_paths(root,contract)
    with store.open(cp) as container, store.open(kp) as commit:
        obj=parse(commit.read())
        h,n=container.hash()
        expected=core.expected_commit(oracle,h,n)
        require(type(obj.get("published_unix_ns")) is int and obj["published_unix_ns"]>0,"COMMIT_TIMESTAMP")
        expected["published_unix_ns"]=obj["published_unix_ns"]
        require(obj==expected,"COMMIT_EXACT_CONTRACT")
        core.validate_commit_without_manifest(kp,oracle,cp,zstd,contract)
        kh,kn=commit.hash()
        return {"container":{"sha256":h,"bytes":n},"commit":{"sha256":kh,"bytes":kn},
                "record":core.manifest_record(oracle,h,n,kh),"oracle":oracle,
                "published_unix_ns":obj["published_unix_ns"]}


def exact_canonical_inventory(store,root,days,allow_lock=True):
    expected={MANIFEST_NAME}
    for key,c in days.items():
        _,cp,kp=day_paths(root,c)
        expected.update((cp.relative_to(root).as_posix(),kp.relative_to(root).as_posix()))
    actual=store.inventory(root)
    if allow_lock:
        actual=[item for item in actual if item["path"]!="TICKSTORE_WRITER.lock"]
    require({item["path"] for item in actual}==expected,"CANONICAL_EXACT_NAMESPACE")
    return actual


class Recovery:
    """Single writer. Persisted intents/coordinators are diagnostics, never admission."""
    def __init__(self,store,config,days,months,c0,s0,zstd,vss,source_bytes=None,deadline_profile=None):
        self.store,self.config,self.days,self.months=store,config,days,months
        self.c0,self.s0,self.zstd,self.vss=c0,s0,zstd,vss
        self.source_bytes=source_bytes;self.deadline_profile=deadline_profile
        self.prep_diagnostics=[];self.watchdog_diagnostics=[]
        self.dest,self.scratch,self.work=(Path(config[k]) for k in ("dest_root","scratch_root","recovery_root"))
        self.run_id=uuid.uuid4().hex;self.sequence=0;self.live={};self.stop_requested=False
        self.lock=None;self.fault=lambda point:None
        self.initial_timestamp=c0["manifest_updated_unix_ns"]
        require(len(c0["days"])==C0_COUNT and len(s0["days"])==S0_COUNT,"ADMISSION_COUNTS")
        require(set(c0["days"]).isdisjoint(s0["days"]) and set(c0["days"])|set(s0["days"])==set(days),"ADMISSION_SET")
        require(generation_equal(c0["generation"],s0["generation"]),"ADMISSION_GENERATION_MISMATCH")

    def metadata(self,kind,obj):
        self.sequence+=1
        name=f"{kind}.{self.run_id}.{self.sequence:08d}.json";raw=json_bytes(obj)
        if isinstance(getattr(self,"deadline_profile",None),dict) and "metadata_hard_deadline_seconds" in self.deadline_profile:
            progress={"bytes":0}
            def operation(update):
                result=self.store.immutable(self.work,name,raw);progress["bytes"]=len(raw);update(progress);return result
            _,diagnostics=monitored_operation("metadata:"+kind,self.deadline_profile["metadata_hard_deadline_seconds"],
                self.deadline_profile["liveness_fatal_seconds"],self.deadline_profile["heartbeat_target_seconds"],
                operation,lambda:dict(progress))
            self.watchdog_diagnostics.extend(diagnostics)
        else:
            self.store.immutable(self.work,name,raw)
        return name

    def acquire(self):
        self.lock=self.store.open(self.dest/"TICKSTORE_WRITER.lock",new=True,mutate=True)
        self.lock.write(json_bytes({"run_id":self.run_id,"pid":os.getpid(),
            "process_creation_time":process_creation_time(os.getpid()),"anchor_sha256":self.config["anchor_sha256"]}))
        self.lock.flush()

    def release(self):
        require(self.lock is not None,"LOCK_NOT_OWNED")
        path=self.lock.path
        self.lock.delete_lock();self.lock.close();self.lock=None
        require(not self.store.exists(path),"LOCK_RELEASE_NOT_ABSENT")

    def live_equality(self):
        # Deliberately independent of global manifest existence.
        for key,entry in sorted(self.c0["days"].items()):
            _,cp,kp=day_paths(self.dest,self.days[key])
            for kind,path in (("container",cp),("commit",kp)):
                with self.store.open(path) as f:
                    require(f.hash()==(entry[kind]["sha256"],entry[kind]["bytes"]),"C0_LIVE_EQUALITY:"+key)
        for key,entry in sorted(self.s0["days"].items()):
            for kind in ("journal","partial"):
                path=self.scratch.joinpath(*relative_path(entry[kind]["path"]))
                with self.store.open(path) as f:
                    require(f.hash()==(entry[kind]["sha256"],entry[kind]["bytes"]),"S0_LIVE_EQUALITY:"+key)
                    if kind=="journal":
                        j=parse(f.read())
                        require(j["oracle"]==entry["contract"] and j["state"]=="VALIDATED_PENDING_PUBLISH","S0_LIVE_CONTRACT")

    def fresh_prep(self,key):
        c=self.days[key]
        if key not in self.live:
            item=prep(self.store,self.scratch,self.s0["days"][key],c,self.months[c["month_id"]],self.zstd)
            self.live[key]=item
        item=self.live[key]
        for kind in ("journal","partial"):
            path=self.scratch.joinpath(*relative_path(self.s0["days"][key][kind]["path"]))
            with self.store.open(path) as current:
                require(current.info()==item["evidence"][kind]["identity"],"PREP_PHYSICAL_IDENTITY_EXPIRED:"+kind)
                if kind=="journal":
                    require(current.hash()==(item["evidence"][kind]["sha256"],item["evidence"][kind]["bytes"]),"PREP_JOURNAL_BYTES_EXPIRED")
        return item

    def prepare_all(self):
        require(self.source_bytes is not None and self.deadline_profile is not None,"PREP_SUPERVISOR_CONFIG_REQUIRED")
        workers=self.config.get("prep_workers")
        require(type(workers) is int and 1<=workers<=MAX_PREP_WORKERS,"PREP_WORKERS_GATE")
        supervisor=PrepSupervisor(self.source_bytes,self.scratch,self.days,self.months,self.s0,self.deadline_profile,workers,lambda:self.stop_requested)
        self.live=supervisor.run();self.prep_diagnostics=list(supervisor.diagnostics)
        self.metadata("prep_complete",{"schema":"PREP_SUPERVISOR_RESULT_V004","workers":workers,"days":len(self.live),
            "diagnostics":self.prep_diagnostics,"source_sha256":sha(self.source_bytes)})

    def physical_records(self):
        records={};partial=[];timestamp=self.initial_timestamp
        for key,c in sorted(self.days.items()):
            _,cp,kp=day_paths(self.dest,c)
            ce,ke=self.store.exists(cp),self.store.exists(kp)
            require(ce or not ke,"COMMIT_WITHOUT_CONTAINER:"+key)
            if key in self.c0["days"]:
                require(ce and ke,"C0_MISSING:"+key)
                oracle=self.c0["days"][key]["oracle"]
            elif ce or ke:
                oracle=self.fresh_prep(key)["oracle"]
            else:
                continue
            if ce and not ke:
                partial.append(key)
                with self.store.open(cp) as f:
                    require(f.hash()==(self.live[key]["container_sha256"],self.live[key]["container_bytes"]),"PARTIAL_CONTAINER_DIVERGENT")
                continue
            pair=validate_pair(self.store,self.dest,c,oracle,self.zstd)
            if key in self.c0["days"]:
                require(pair==self.c0["days"][key],"C0_CONTRACT_DIVERGENT")
            else:
                item=self.live[key]
                require(pair["container"]=={"sha256":item["container_sha256"],"bytes":item["container_bytes"]},"R_PREP_MISMATCH")
                item["pair"]=pair
                timestamp=max(timestamp,pair["published_unix_ns"])
            records[key]=pair["record"]
        require(len(partial)<=1,"MULTIPLE_PARTIAL_S0_DAYS")
        return records,timestamp

    def startup_manifest(self,records,timestamp):
        path=self.dest/MANIFEST_NAME
        if self.store.exists(path):
            with self.store.open(path) as f:
                raw=f.read();obj=parse(raw)
                require(obj.get("schema")==MANIFEST_SCHEMA,"GLOBAL_MANIFEST_DIVERGENT")
                # One already published C/K pair may still await its manifest phase.
                require(set(obj["records"])<=set(records) and
                        all(records[k]==v for k,v in obj["records"].items()),"GLOBAL_MANIFEST_DIVERGENT")
                require(set(self.c0["days"])<=set(obj["records"]),"C0_MANIFEST_MISSING")
                require(len(set(records)-set(obj["records"]))<=1,"MULTIPLE_PENDING_MANIFEST_DAYS")
                rederive_manifest(raw,obj["records"])
                return obj
        expected=manifest_bytes(records,timestamp)
        candidates=[]
        with self.store.open(self.work,directory=True):
            for candidate_path in sorted(self.work.iterdir()):
                if re.fullmatch(r"manifest\.(pre|post)\.[0-9a-f]{32}\.[0-9a-f]{32}\.json",candidate_path.name):
                    with self.store.open(candidate_path) as f:
                        raw=f.read()
                        if raw==expected:
                            candidates.append((candidate_path,raw))
        selected=manifest_candidate(candidates,expected)
        with self.store.open(self.dest,directory=True) as directory, self.store.open(selected,mutate=True) as staged:
            require(staged.read()==expected,"MANIFEST_CANDIDATE_CHANGED")
            staged.rename(directory,MANIFEST_NAME);staged.flush()
        with self.store.open(path) as final:
            require(final.read()==expected,"MANIFEST_RESTORE_MISMATCH")
        return parse(expected)

    def classify(self,manifest):
        states={}
        for key,c in sorted(self.days.items()):
            _,cp,kp=day_paths(self.dest,c)
            states[key]=classify_day(self.store.exists(cp),self.store.exists(kp),key in manifest["records"])
        classify_set(states,set(self.c0["days"]))
        return states

    def publish(self,key,manifest,state):
        require(not self.stop_requested,"STOP_BEFORE_INTENT")
        c=self.days[key];item=self.fresh_prep(key);core=frozen_core()
        txn=uuid.uuid4().hex
        _,cp,kp=day_paths(self.dest,c)
        # New month directories are explicit owner-gate preparation, never guessed/created here.
        timestamp=max(time.time_ns(),manifest["updated_unix_ns"]+1)
        if state=="CONTAINER_COMMIT":
            with self.store.open(kp) as f:
                commit_raw=f.read();commit=parse(commit_raw)
            pair=validate_pair(self.store,self.dest,c,item["oracle"],self.zstd)
            timestamp=pair["published_unix_ns"]
        else:
            commit=core.expected_commit(item["oracle"],item["container_sha256"],item["container_bytes"])
            commit["published_unix_ns"]=timestamp;commit_raw=json_bytes(commit)
        record=core.manifest_record(item["oracle"],item["container_sha256"],item["container_bytes"],sha(commit_raw))
        after=dict(manifest["records"]);after[key]=record
        post_raw=manifest_bytes(after,max(timestamp,manifest["updated_unix_ns"]))
        pre_name=f"manifest.pre.{self.run_id}.{txn}.json"
        post_name=f"manifest.post.{self.run_id}.{txn}.json"
        with contextlib.ExitStack() as stack:
            dest_dir=stack.enter_context(self.store.open(cp.parent,directory=True))
            root_dir=stack.enter_context(self.store.open(self.dest,directory=True))
            work_dir=stack.enter_context(self.store.open(self.work,directory=True))
            current=stack.enter_context(self.store.open(self.dest/MANIFEST_NAME,mutate=True))
            require(current.read()==json_bytes(manifest),"MANIFEST_PREIMAGE_CHANGED")
            stage_c=None
            if state=="PENDING":
                stage_c=stack.enter_context(self.store.open(self.work/f"container.{self.run_id}.{txn}.stage",new=True,mutate=True))
                source_path=self.scratch.joinpath(*relative_path(self.s0["days"][key]["partial"]["path"]))
                with self.store.open(source_path) as source:
                    require(source.info()==item["evidence"]["partial"]["identity"],"PREP_PHYSICAL_IDENTITY_EXPIRED")
                    deadline=self.deadline_profile["streaming_by_size_class"][size_class(item["container_bytes"])]
                    progress={"bytes":0}
                    def copy_stage(update):
                        for chunk in source.chunks():
                            stage_c.write(chunk);progress["bytes"]+=len(chunk);update(progress)
                        stage_c.flush();return stage_c.hash()
                    stage_hash,diagnostics=monitored_operation("publish-stage:"+key,deadline,
                        self.deadline_profile.get("liveness_fatal_seconds",45),self.deadline_profile.get("heartbeat_target_seconds",5),
                        copy_stage,lambda:dict(progress))
                    self.watchdog_diagnostics.extend(diagnostics)
                require(stage_hash==(item["container_sha256"],item["container_bytes"]),"STAGE_COPY_MISMATCH")
            stage_k=None
            if state!="CONTAINER_COMMIT":
                stage_k=stack.enter_context(self.store.open(self.work/f"commit.{self.run_id}.{txn}.stage",new=True,mutate=True))
                stage_k.write(commit_raw);stage_k.flush()
                require(stage_k.hash()==(sha(commit_raw),len(commit_raw)),"COMMIT_STAGE_MISMATCH")
            post=stack.enter_context(self.store.open(self.work/post_name,new=True,mutate=True))
            post.write(post_raw);post.flush()
            require(post.hash()==(sha(post_raw),len(post_raw)),"MANIFEST_STAGE_MISMATCH")
            self.fault("BEFORE_INTENT")
            self.metadata("intent",{"schema":"PUBLISH_INTENT_V004","run_id":self.run_id,"txn":txn,"date_key":key,
                "prep_sha256":sha(stable(item)),"scratch_identity":item["evidence"],
                "container_stage":stage_c.info() if stage_c else None,"container_sha256":item["container_sha256"],
                "commit_stage":stage_k.info() if stage_k else None,"commit_sha256":sha(commit_raw),
                "manifest_pre_identity":current.info(),"manifest_pre_sha256":sha(json_bytes(manifest)),
                "manifest_post_identity":post.info(),"manifest_post_sha256":sha(post_raw),"record":record,
                "before_set_sha256":sha(stable(sorted(manifest["records"]))),"after_set_sha256":sha(stable(sorted(after))),
                "rows_before":sum(int(self.days[k]["rows"]) for k in manifest["records"]),
                "rows_after":sum(int(self.days[k]["rows"]) for k in after)})
            self.fault("AFTER_INTENT")
            if stage_c:
                stage_c.rename(dest_dir,cp.name);stage_c.flush()
            self.fault("AFTER_CONTAINER_RENAME")
            if stage_k:
                stage_k.rename(dest_dir,kp.name);stage_k.flush()
            self.fault("AFTER_COMMIT_RENAME")
            current.rename(work_dir,pre_name);current.flush()
            self.fault("MANIFEST_PRE_MOVED")
            post.rename(root_dir,MANIFEST_NAME);post.flush()
            self.fault("MANIFEST_POST_MOVED")
        pair=validate_pair(self.store,self.dest,c,item["oracle"],self.zstd)
        require(pair["record"]==record,"PUBLISHED_RECORD_MISMATCH")
        with self.store.open(self.dest/MANIFEST_NAME) as final:
            require(final.read()==post_raw,"PUBLISHED_MANIFEST_MISMATCH")
        item["pair"]=pair
        self.fault("BEFORE_COORDINATOR")
        self.metadata("coordinator",{"schema":"COORDINATOR_GENERATION_V004","authority":False,
            "run_id":self.run_id,"completed":sorted(after),"rows":sum(int(self.days[k]["rows"]) for k in after),
            "last_date_key":key,"manifest_sha256":sha(post_raw)})
        return parse(post_raw)

    def audit_snapshot(self,generation,final=False):
        self.vss.assert_present(generation)
        root=self.vss.shadow_root(generation,self.dest)
        with self.store.open(root/MANIFEST_NAME) as f:
            raw=f.read();manifest=parse(raw)
        records=manifest["records"]
        expected=set(self.days) if final else set(self.c0["days"])|{k for k,v in self.live.items() if "pair" in v}
        require(set(records)==expected,"SNAPSHOT_CANONICAL_DATE_SET")
        for key in sorted(expected):
            admitted=self.c0["days"].get(key) or self.live[key]["pair"]
            pair=validate_pair(self.store,root,self.days[key],admitted["oracle"],self.zstd)
            require(pair==admitted and records[key]==pair["record"],"SNAPSHOT_CANONICAL_BINDING:"+key)
        rederive_manifest(raw,records)
        inventory=exact_canonical_inventory(self.store,root,{k:self.days[k] for k in expected})
        rows=sum(int(self.days[k]["rows"]) for k in expected)
        if final:
            require(len(expected)==TOTAL_DAYS and rows==TOTAL_ROWS,"FINAL_1550_ROWS")
        self.vss.assert_present(generation)
        return {"pass":True,"generation":generation,"inventory":inventory,"inventory_sha256":sha(stable(inventory)),
                "manifest_sha256":sha(raw),"set_sha256":sha(stable(sorted(expected))),"days":len(expected),"rows":rows}

    def safe_stop(self):
        result={"schema":"SAFE_STOP_RESULT_V004","SAFE_STOP":"NO","INTERRUPTED_RECONCILIATION_REQUIRED":"YES"}
        try:
            require(job_members()=={os.getpid()},"RESIDUAL_CHILDREN")
            # No repair is performed during closure: a missing manifest or partial pair blocks YES.
            generation=self.vss.create("SAFE_STOP")
            canonical=self.audit_snapshot(generation)
            scratch_root=self.vss.shadow_root(generation,self.scratch)
            observed=scan_s0(self.store,scratch_root)
            s0=s0_inventory_gate(self.s0,observed,generation)
            result.update({"canonical":canonical,"s0":s0,"scratch_admission_cert_sha256":self.config["scratch_admission_cert_sha256"],
                           "SAFE_STOP":safe_stop_decision(canonical,s0)})
            self.vss.assert_present(generation)
        except Exception as exc:
            result["error"]=str(exc)
        if result["SAFE_STOP"]=="YES":
            result["INTERRUPTED_RECONCILIATION_REQUIRED"]="NO"
        self.metadata("safe_stop",result)
        self.release()
        print("SAFE_STOP="+result["SAFE_STOP"],flush=True)
        return 130

    def run(self):
        require(job_members()=={os.getpid()},"RECOVERY_JOB_MEMBERSHIP")
        watcher=NamedStopEvent(self.config["safe_stop_event_name"],lambda:setattr(self,"stop_requested",True))
        watcher.start()
        self.acquire()
        old=signal.getsignal(signal.SIGINT)
        def stop(signum,frame):
            self.stop_requested=True
        signal.signal(signal.SIGINT,stop)
        try:
            self.live_equality()
            observed=scan_s0(self.store,self.scratch)
            require(s0_inventory_gate(self.s0,observed,self.s0["generation"])["pass"],"LIVE_S0_NAMESPACE")
            self.vss.startup_probe(self.dest,self.scratch)
            self.prepare_all()
            records,timestamp=self.physical_records()
            manifest=self.startup_manifest(records,timestamp)
            states=self.classify(manifest)
            for key in sorted(self.s0["days"],key=lambda k:(states[k]=="PENDING",k)):
                if self.stop_requested:
                    return self.safe_stop()
                if states[key]=="TERMINAL":
                    continue
                manifest=self.publish(key,manifest,states[key])
            if self.stop_requested:
                return self.safe_stop()
            generation=self.vss.create("FINAL")
            final=self.audit_snapshot(generation,final=True)
            self.vss.assert_present(generation)
            self.metadata("final_reconcile",{"schema":"FINAL_RECONCILE_RESULT_V004",**final})
            self.vss.assert_present(generation)
            self.release()
            self.metadata("completion",{"schema":SCHEMA,"result":"PASS","snapshot_id":generation["snapshot_id"],
                                         "promotion_authorized":False})
            print(SCHEMA+"=PASS",flush=True)
            return 0
        except KeyboardInterrupt:
            return self.safe_stop()
        except BaseException:
            # Keep stale lock metadata for separate explicit audit. Close OS resources only.
            if self.lock is not None:
                self.lock.close();self.lock=None
            raise
        finally:
            signal.signal(signal.SIGINT,old)
            watcher.close()


def scan_s0(store,root):
    root=Path(root);objects=[]
    def walk(directory,namespace):
        with store.open(directory,directory=True):
            for entry in sorted(os.scandir(directory),key=lambda e:e.name):
                st=entry.stat(follow_symlinks=False)
                require(not(getattr(st,"st_file_attributes",0)&0x400),"S0_REPARSE")
                if entry.is_dir(follow_symlinks=False):
                    walk(Path(entry.path),namespace)
                else:
                    match=re.fullmatch(r"(\d{8})\.(journal\.json|pts2g\.partial)",entry.name)
                    if not match:
                        continue
                    path=Path(entry.path);key=match[1]
                    kind="journal" if match[2]=="journal.json" else "partial"
                    with store.open(path) as f:
                        h,n=f.hash()
                        obj={"date_key":key,"kind":kind,"path":path.relative_to(root).as_posix(),
                             "namespace":namespace,"sha256":h,"bytes":n,"links":f.info()["links"],"reparse":False}
                        if kind=="journal":
                            j=parse(f.read())
                            require(j.get("state")=="VALIDATED_PENDING_PUBLISH","S0_JOURNAL_STATE")
                            obj["contract"]=j.get("oracle")
                        objects.append(obj)
    for namespace in NAMESPACES:
        if store.exists(root/namespace):
            walk(root/namespace,namespace)
    return objects


def process_creation_time(pid):
    require(os.name=="nt","PROCESS_IDENTITY_WINDOWS")
    k=ctypes.WinDLL("kernel32",use_last_error=True)
    k.OpenProcess.restype=HANDLE;k.OpenProcess.argtypes=[U32,BOOL,U32]
    k.GetProcessTimes.argtypes=[HANDLE,HANDLE,HANDLE,HANDLE,HANDLE]
    k.CloseHandle.argtypes=[HANDLE]
    h=k.OpenProcess(0x1000,False,pid)
    if not h:
        require(ctypes.get_last_error()==87,"PROCESS_CENSUS_ACCESS_DENIED")
        return None
    try:
        values=[U64() for _ in range(4)]
        Win32Store.check(k.GetProcessTimes(h,*(ctypes.byref(v) for v in values)),"PROCESS_TIMES")
        return values[0].value
    finally:
        k.CloseHandle(h)


def job_members():
    require(os.name=="nt","JOB_WINDOWS_REQUIRED")
    k=ctypes.WinDLL("kernel32",use_last_error=True)
    k.QueryInformationJobObject.argtypes=[HANDLE,ctypes.c_int,HANDLE,U32,HANDLE]
    # NULL means the calling process's job; no inheritable job handle keeps the root job alive.
    buf=ctypes.create_string_buffer(8+256*ctypes.sizeof(ctypes.c_size_t))
    Win32Store.check(k.QueryInformationJobObject(None,3,buf,len(buf),None),"JOB_ACCOUNTING")
    assigned=U32.from_buffer(buf,0).value;count=U32.from_buffer(buf,4).value
    require(count==assigned and count<=256,"JOB_MEMBERSHIP_TRUNCATED")
    return set((ctypes.c_size_t*count).from_buffer(buf,8))


TH32CS_SNAPPROCESS=0x00000002
PROCESS_QUERY_LIMITED_INFORMATION=0x1000


class PROCESSENTRY32W(ctypes.Structure):
    _fields_=[("dwSize",U32),("cntUsage",U32),("th32ProcessID",U32),("th32DefaultHeapID",ctypes.c_size_t),
              ("th32ModuleID",U32),("cntThreads",U32),("th32ParentProcessID",U32),("pcPriClassBase",ctypes.c_long),
              ("dwFlags",U32),("szExeFile",w.WCHAR*260)]


def recovery_process_census():
    """Conservative native process census for the exact admitted Python runtime.

    Every recovery supervisor/worker executes under the same pinned interpreter.  A
    second live process using that exact executable is therefore a blocker for the
    explicit stale-lock-clear mode.  Unreadable same-basename candidates also block.
    """
    require(os.name=="nt","PROCESS_CENSUS_WINDOWS_REQUIRED")
    k=ctypes.WinDLL("kernel32",use_last_error=True)
    k.CreateToolhelp32Snapshot.restype=HANDLE
    k.CreateToolhelp32Snapshot.argtypes=[U32,U32]
    k.Process32FirstW.argtypes=[HANDLE,ctypes.POINTER(PROCESSENTRY32W)]
    k.Process32NextW.argtypes=[HANDLE,ctypes.POINTER(PROCESSENTRY32W)]
    k.OpenProcess.restype=HANDLE;k.OpenProcess.argtypes=[U32,BOOL,U32]
    k.QueryFullProcessImageNameW.argtypes=[HANDLE,U32,w.LPWSTR,ctypes.POINTER(U32)]
    k.CloseHandle.argtypes=[HANDLE]
    snap=k.CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS,0)
    Win32Store.check(snap!=ctypes.c_void_p(-1).value,"PROCESS_CENSUS_SNAPSHOT")
    expected=norm(sys.executable);base=os.path.basename(expected).lower();current=os.getpid();known=[];unreadable=[]
    try:
        entry=PROCESSENTRY32W();entry.dwSize=ctypes.sizeof(PROCESSENTRY32W)
        ok=k.Process32FirstW(snap,ctypes.byref(entry))
        while ok:
            pid=int(entry.th32ProcessID);exe=str(entry.szExeFile)
            if pid!=current and exe.lower()==base:
                h=k.OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION,False,pid)
                if not h:
                    unreadable.append({"pid":pid,"exe":exe})
                else:
                    try:
                        cap=U32(32768);buf=ctypes.create_unicode_buffer(cap.value)
                        if not k.QueryFullProcessImageNameW(h,0,buf,ctypes.byref(cap)):
                            unreadable.append({"pid":pid,"exe":exe})
                        elif norm(buf.value)==expected:
                            known.append({"pid":pid,"process_creation_time":process_creation_time(pid),"image":buf.value})
                    finally:
                        k.CloseHandle(h)
            ok=k.Process32NextW(snap,ctypes.byref(entry))
    finally:
        k.CloseHandle(snap)
    require(not unreadable,"PROCESS_CENSUS_UNREADABLE_PYTHON:"+json.dumps(unreadable,sort_keys=True))
    return {"current_pid":current,"python_executable":sys.executable,"known_recovery_candidates":known,
            "known_recovery_supervisor_or_workers":len(known)}


class GUID(ctypes.Structure):
    _fields_=[("Data1",U32),("Data2",ctypes.c_uint16),("Data3",ctypes.c_uint16),("Data4",ctypes.c_ubyte*8)]

    @classmethod
    def from_text(cls,value):
        return cls.from_buffer_copy(uuid.UUID(value).bytes_le)

    def text(self):
        return str(uuid.UUID(bytes_le=bytes(self)))


class VSS_SNAPSHOT_PROP(ctypes.Structure):
    _fields_=[("SnapshotId",GUID),("SnapshotSetId",GUID),("SnapshotsCount",ctypes.c_int32),
        ("DeviceObject",w.LPWSTR),("OriginalVolume",w.LPWSTR),("OriginatingMachine",w.LPWSTR),
        ("ServiceMachine",w.LPWSTR),("ExposedName",w.LPWSTR),("ExposedPath",w.LPWSTR),
        ("ProviderId",GUID),("Attributes",ctypes.c_int32),("CreationTimestamp",ctypes.c_int64),("Status",ctypes.c_int32)]


class NativeVSS:
    """Direct IVssBackupComponents ABI. Native calls are never used by fixture tests."""
    def __init__(self,store,profile):
        require(os.name=="nt","VSS_WINDOWS_REQUIRED")
        self.store,self.profile=store,profile
        require(profile["context"]==25,"VSS_CONTEXT_REQUIRES_NAS_ROLLBACK")
        require(profile.get("snapshot_execution_authorized") is True,"VSS_EXECUTION_NOT_AUTHORIZED")
        require(ctypes.WinDLL("shell32").IsUserAnAdmin(),"VSS_ELEVATION_REQUIRED")
        self.ole=ctypes.OleDLL("ole32")
        self.ole.CoInitializeEx(None,0)
        self.dll=ctypes.WinDLL("vssapi")
        self.dll.CreateVssBackupComponentsInternal.argtypes=[ctypes.POINTER(HANDLE)]
        self.dll.CreateVssBackupComponentsInternal.restype=ctypes.c_int32
        self.ptr=HANDLE()
        self.hr(self.dll.CreateVssBackupComponentsInternal(ctypes.byref(self.ptr)))
        self.call(5,[w.LPWSTR],None)  # InitializeForBackup
        self.call(35,[ctypes.c_int32],25)  # SetContext

    @staticmethod
    def hr(value):
        require(value>=0,"VSS_HRESULT:"+hex(value & 0xffffffff))

    def invoke(self,ptr,index,args,*values):
        table=ctypes.cast(ptr,ctypes.POINTER(ctypes.POINTER(HANDLE))).contents
        fn=ctypes.WINFUNCTYPE(ctypes.c_int32,HANDLE,*args)(table[index])
        result=fn(ptr,*values);self.hr(result);return result

    def call(self,index,args,*values):
        return self.invoke(self.ptr,index,args,*values)

    def properties(self,snapshot_id):
        prop=VSS_SNAPSHOT_PROP();sid=GUID.from_text(snapshot_id)
        self.call(42,[GUID,ctypes.POINTER(VSS_SNAPSHOT_PROP)],sid,ctypes.byref(prop))
        try:
            result={"snapshot_id":prop.SnapshotId.text(),"snapshot_set_id":prop.SnapshotSetId.text(),
                "provider_id":prop.ProviderId.text(),"device_object":prop.DeviceObject,
                "volume_identity":self.profile["volume_identity"],"volume_guid":prop.OriginalVolume,
                "creation_timestamp":prop.CreationTimestamp,"attributes":prop.Attributes}
            require(result["provider_id"]==self.profile["provider_id"],"VSS_PROVIDER_MISMATCH")
            require(prop.Attributes&1 and prop.Attributes&8 and prop.Attributes&16,"VSS_CONTEXT_ATTRIBUTES")
            require(prop.OriginalVolume.lower()==self.profile["volume_guid"].lower(),"VSS_VOLUME_MISMATCH")
            return result
        finally:
            self.dll.VssFreeSnapshotPropertiesInternal.argtypes=[ctypes.POINTER(VSS_SNAPSHOT_PROP)]
            self.dll.VssFreeSnapshotPropertiesInternal(ctypes.byref(prop))

    def create(self,purpose):
        set_id,sid=GUID(),GUID();async_ptr=HANDLE()
        self.call(36,[ctypes.POINTER(GUID)],ctypes.byref(set_id))
        self.call(37,[w.LPWSTR,GUID,ctypes.POINTER(GUID)],self.profile["volume_guid"],
                  GUID.from_text(self.profile["provider_id"]),ctypes.byref(sid))
        self.call(38,[ctypes.POINTER(HANDLE)],ctypes.byref(async_ptr))
        started=time.monotonic()
        try:
            while True:
                status=ctypes.c_int32();reserved=ctypes.c_int32()
                self.invoke(async_ptr,5,[ctypes.POINTER(ctypes.c_int32),ctypes.POINTER(ctypes.c_int32)],ctypes.byref(status),ctypes.byref(reserved))
                if status.value==0x4230a:
                    break
                self.hr(status.value)
                require(status.value==0x42309,"VSS_ASYNC_NOT_FINISHED")
                require(time.monotonic()-started<self.profile["create_deadline_seconds"],"VSS_DEADLINE")
                time.sleep(0.2)
        finally:
            self.invoke(async_ptr,2,[])  # IUnknown::Release
        generation=self.properties(sid.text())
        require(generation["snapshot_set_id"]==set_id.text(),"VSS_SET_ID_MISMATCH")
        generation["purpose"]=purpose
        return generation

    def assert_present(self,generation):
        current=self.properties(generation["snapshot_id"])
        require(generation_equal(current,generation),"VSS_GENERATION_LOST_OR_CHANGED")

    def shadow_root(self,generation,live_root):
        require(PureWindowsPath(live_root).drive.upper()==self.profile["drive"].upper(),"VSS_ROOT_VOLUME")
        relative=PureWindowsPath(live_root).parts[1:]
        return Path(generation["device_object"]+"\\").joinpath(*relative)

    def startup_probe(self,dest,scratch):
        generation=self.create("STARTUP_PROBE")
        for root in (dest,scratch):
            with self.store.open(self.shadow_root(generation,root),directory=True):
                pass
        count=ctypes.c_int32();nondeleted=GUID()
        self.call(39,[GUID,ctypes.c_int32,BOOL,ctypes.POINTER(ctypes.c_int32),ctypes.POINTER(GUID)],
                  GUID.from_text(generation["snapshot_id"]),3,False,ctypes.byref(count),ctypes.byref(nondeleted))
        require(count.value==1,"VSS_PROBE_CLEANUP_FAILED")
        try:
            self.properties(generation["snapshot_id"])
        except Blocked as exc:
            require("80042308" in str(exc).lower(),"VSS_PROBE_CLEANUP_UNCONFIRMED")
        else:
            raise Blocked("VSS_PROBE_STILL_PRESENT")

    def close(self):
        if self.ptr:
            self.call(2,[]);self.ptr=None
            self.ole.CoUninitialize()


def admit_bundle(anchor,members):
    require(anchor.get("inline_root_loader_revision")=="INLINE_ROOT_LOADER_V004_R1","ROOT_LOADER_REVISION")
    require(anchor.get("spec_sha256")==SPEC_SHA,"SPEC_ANCHOR")
    require(anchor.get("python_version")=="3.14.7","PYTHON_ANCHOR")
    for name,value in members.items():
        basename(name)
        require(isinstance(value,bytes),"BUNDLE_MEMBER_BYTES")
    manifest_raw=members["RELEASE_MANIFEST.json"]
    require(sha(manifest_raw)==digest(anchor["release_manifest_sha256"]),"RELEASE_MANIFEST_HASH")
    manifest=parse(manifest_raw)
    require(set(manifest)=={"schema","members"} and manifest["schema"]=="RELEASE_MANIFEST_V004","RELEASE_MANIFEST_SCHEMA")
    require(set(manifest["members"])==set(members)-{"RELEASE_MANIFEST.json"},"BUNDLE_MEMBER_SET")
    executable=[name for name in members if name.endswith((".py",".pyc",".pyd",".ps1",".exe",".dll"))]
    require(executable==["tickstore_publisher_recovery_v004.py"],"SINGLE_EXECUTABLE_MEMBER")
    for name,item in manifest["members"].items():
        require(set(item)=={"sha256","bytes"} and sha(members[name])==item["sha256"] and len(members[name])==item["bytes"],"BUNDLE_MEMBER_HASH:"+name)
    require(sha(members["tickstore_publisher_recovery_v004.py"])==anchor["recovery_source_sha256"],"SOURCE_ANCHOR_HASH")
    require(sha(members["OWNER_GATE.json"])==anchor["owner_gate_sha256"],"OWNER_GATE_ANCHOR_HASH")
    gate=parse(members["OWNER_GATE.json"])
    require("release_bundle_sha256" not in gate and "external_anchor_sha256" not in gate,"CYCLIC_OWNER_GATE")
    require(gate.get("schema")=="RECOVERY_OWNER_GATE_V004" and gate.get("authorized") is True,"OWNER_GATE_NOT_AUTHORIZED")
    for field in ("spec_sha256","recovery_source_sha256","python_exe_sha256","python_version","release_id"):
        require(gate.get(field)==anchor[field],"OWNER_GATE_BINDING:"+field)
    require(gate.get("rescan_authorized") is False and gate.get("csv_deletion_authorized") is False
            and gate.get("format_promotion_authorized") is False and gate.get("codec_promotion_authorized") is False,
            "FORBIDDEN_PERMISSION")
    mode=gate["mode"]
    allowed={"RECOVER","CERTIFY_SCRATCH","CERTIFY_CANONICAL","MANIFEST_REDERIVATION","LIVE_EQUALITY","PROMOTION_CHECK","STALE_LOCK"}
    require(mode in allowed,"RECOVERY_MODE")
    require(gate.get("permissions",{}).get(mode) is True,"MODE_NOT_AUTHORIZED")
    if mode=="RECOVER":
        require(gate.get("production_recovery_authorized") is True or gate.get("canary_execution_authorized") is True,"EXECUTION_NOT_AUTHORIZED")
        require(gate["canary_recovery_source_sha256"]==anchor["recovery_source_sha256"],"CANARY_PRODUCTION_CODE_CHANGED")
        safe_stop_event_name(gate.get("safe_stop_event_name"))
    # Every artifact is data and independently sealed by the external release anchor.
    for member,field in (("SCRATCH_CERT.json","scratch_admission_cert_sha256"),
                         ("CANONICAL_CERT.json","canonical_admission_cert_sha256"),
                         ("DEADLINE_PROFILE.json","deadline_profile_sha256")):
        if member in members:
            require(sha(members[member])==anchor[field]==gate[field],"AUTHORITY_DATA_BINDING:"+member)
    return gate


def validate_roots(store,gate):
    roots={key:Path(gate[key]) for key in ("dest_root","scratch_root","recovery_root")}
    normalized=[norm(value) for value in roots.values()]
    require(len(set(normalized))==3,"ROOT_ALIAS")
    for a in normalized:
        for b in normalized:
            if a!=b:
                require(not b.startswith(a+os.sep),"ROOT_OVERLAP")
    for key,path in roots.items():
        with store.open(path,directory=True) as f:
            expected=gate["root_bindings"][key]
            require(f.info()==expected,"ROOT_BINDING:"+key)
    if gate.get("production_recovery_authorized") is not True:
        protected=(norm(r"D:\TICKSTORE"),norm(r"D:\TICKSTORE_GATE_B_SCRATCH"),norm(r"D:\Base CSV\WIN@N"))
        require(all(not(p==q or p.startswith(q+os.sep) or q.startswith(p+os.sep)) for p in normalized for q in protected),"CANARY_PRODUCTION_ROOT")


def certify_scratch(store,root,inventory,days,months,zstd,generation,source_sha):
    require(len(inventory)==S0_COUNT,"S0_CERT_REQUIRED_1399")
    observed=scan_s0(store,root);mapped={}
    for obj in observed:
        require(obj["date_key"] in inventory,"S0_CERT_UNEXPECTED")
        pair=mapped.setdefault(obj["date_key"],{})
        require(obj["kind"] not in pair,"S0_CERT_DUPLICATE")
        pair[obj["kind"]]=obj
    require(set(mapped)==set(inventory),"S0_CERT_MISSING")
    result={}
    for key,pair in sorted(mapped.items()):
        require(set(pair)=={"journal","partial"},"S0_CERT_ORPHAN")
        require(pair["journal"]["namespace"]==pair["partial"]["namespace"],"S0_CERT_NAMESPACE_ASSOCIATION")
        require(pair["journal"]["path"]==inventory[key]["journal"] and pair["partial"]["path"]==inventory[key]["partial"],"S0_CERT_PATH_ASSOCIATION")
        entry={"namespace":pair["journal"]["namespace"],"contract":pair["journal"]["contract"]}
        for kind in ("journal","partial"):
            entry[kind]={field:pair[kind][field] for field in ("path","sha256","bytes")}
        c=days[key]
        prep(store,root,entry,c,months[c["month_id"]],zstd)
        result[key]=entry
    return {"schema":"SCRATCH_ADMISSION_CERT_V004","result":"PASS_1399_1399","generation":generation,
            "source_sha256":source_sha,"ledger_sha256":LEDGER_SHA,"days":result}


def certify_canonical(store,root,inventory,days,zstd,generation,source_sha):
    require(len(inventory)==C0_COUNT,"C0_CERT_REQUIRED_151")
    with store.open(Path(root)/MANIFEST_NAME) as f:
        raw=f.read();manifest=parse(raw)
    require(set(manifest["records"])==set(inventory),"C0_MANIFEST_DATE_SET")
    result={}
    for key,oracle in sorted(inventory.items()):
        pair=validate_pair(store,root,days[key],oracle,zstd)
        require(manifest["records"][key]==pair["record"],"C0_MANIFEST_RECORD")
        result[key]=pair
    rederive_manifest(raw,{key:item["record"] for key,item in result.items()})
    exact_canonical_inventory(store,root,{key:days[key] for key in result})
    return {"schema":"CANONICAL_ADMISSION_CERT_V004","result":"PASS_151_151","generation":generation,
            "source_sha256":source_sha,"ledger_sha256":LEDGER_SHA,"days":result,
            "manifest_sha256":sha(raw),"manifest_updated_unix_ns":manifest["updated_unix_ns"]}


def audit_stale_lock(store,root,work,gate):
    require(gate.get("stale_lock_clear_authorized") is True,"STALE_LOCK_CLEAR_NOT_AUTHORIZED")
    require(job_members()=={os.getpid()},"STALE_LOCK_RESIDUAL_JOB_PROCESSES")
    census=recovery_process_census()
    require(census["known_recovery_supervisor_or_workers"]==0,"STALE_LOCK_PROCESS_CENSUS_NOT_CLEAR")
    # This mode is terminal: never starts a recovery after clearing.
    path=Path(root)/"TICKSTORE_WRITER.lock"
    with store.open(path,mutate=True) as lock:
        raw=lock.read();metadata=parse(raw)
        require(process_creation_time(int(metadata["pid"]))!=metadata["process_creation_time"],"STALE_LOCK_PROCESS_ALIVE")
        evidence={"schema":"STALE_LOCK_AUDIT_AND_CLEAR_V004","prior_lock_sha256":sha(raw),
                  "prior":metadata,"identity":lock.info(),"clear_authorized":True,
                  "process_census":{**census,"global_supervisor_mutex_exclusive":True,
                                    "current_job_members":sorted(job_members())}}
        store.immutable(work,"stale_lock."+uuid.uuid4().hex+".json",json_bytes(evidence))
        lock.delete_lock()
    require(not store.exists(path),"STALE_LOCK_CLEAR_NOT_ABSENT")
    return 0


def dispatch_bootstrap(payload):
    require(IMPLEMENTATION_READY, IMPLEMENTATION_BLOCKER)
    require(sys.version_info[:3]==(3,14,7) and sys.flags.isolated and sys.flags.no_site,"RUNTIME_CONTRACT")
    require(job_members()=={os.getpid()},"JOB_ASSIGNMENT_REQUIRED_BEFORE_STARTUP")
    with RecoveryProcessLease():
        anchor=payload["anchor"]
        members={name:base64.b64decode(value,validate=True) for name,value in payload["members"].items()}
        gate=admit_bundle(anchor,members)
        gate={**gate,"anchor_sha256":sha(stable(anchor))}
        store=Win32Store();validate_roots(store,gate)
        print("RECOVERY_STARTUP_HANDSHAKE="+anchor["recovery_source_sha256"],flush=True)
        mode=gate["mode"]
        if mode=="STALE_LOCK":
            return audit_stale_lock(store,gate["dest_root"],gate["recovery_root"],gate)
        days,months=ledger_from_bytes(members["LEDGER.zip"])
        deadlines=deadline_contract(gate,members)
        from compression import zstd
        with contextlib.ExitStack() as stack:
            vss=NativeVSS(store,gate["vss"]);stack.callback(vss.close)
            if mode in ("CERTIFY_SCRATCH","CERTIFY_CANONICAL"):
                generation=gate["admission_generation"];vss.assert_present(generation)
                if mode=="CERTIFY_SCRATCH":
                    result=certify_scratch(store,vss.shadow_root(generation,gate["scratch_root"]),gate["s0_inventory"],days,months,zstd,generation,anchor["recovery_source_sha256"])
                else:
                    result=certify_canonical(store,vss.shadow_root(generation,gate["dest_root"]),gate["c0_oracles"],days,zstd,generation,anchor["recovery_source_sha256"])
                vss.assert_present(generation)
                store.immutable(gate["recovery_root"],mode.lower()+"."+uuid.uuid4().hex+".json",json_bytes(result))
                return 0
            c0,s0=parse(members["CANONICAL_CERT.json"]),parse(members["SCRATCH_CERT.json"])
            require(c0["schema"]=="CANONICAL_ADMISSION_CERT_V004" and c0["result"]=="PASS_151_151","C0_CERT_NOT_PASSED")
            require(s0["schema"]=="SCRATCH_ADMISSION_CERT_V004" and s0["result"]=="PASS_1399_1399","S0_CERT_NOT_PASSED")
            require(c0["source_sha256"]==s0["source_sha256"]==anchor["recovery_source_sha256"],"CERTIFICATION_SOURCE_CHANGED")
            engine=Recovery(store,gate,days,months,c0,s0,zstd,vss,members["tickstore_publisher_recovery_v004.py"],deadlines)
            if mode=="LIVE_EQUALITY":
                engine.live_equality();return 0
            if mode=="MANIFEST_REDERIVATION":
                records={key:item["record"] for key,item in c0["days"].items()}
                with store.open(Path(gate["dest_root"])/MANIFEST_NAME) as f:
                    rederive_manifest(f.read(),records)
                return 0
            if mode=="PROMOTION_CHECK":
                raise Blocked("PROMOTION_REQUIRES_INDEPENDENT_FINAL_AUTHORITY_AND_FRESH_SNAPSHOT_AUDIT")
            return engine.run()


def main():
    # PREP workers are internal descendants of an already admitted supervisor.  They
    # must be launchable while the external recovery fuse remains fail-closed so the
    # Windows pre-canary worker contract can be tested without authorizing recovery.
    if "--prep-worker" in sys.argv[1:]:
        ap=argparse.ArgumentParser(description="Internal authenticated PREP worker")
        ap.add_argument("--prep-worker",action="store_true")
        ap.add_argument("--prep-pipe",required=True)
        ap.add_argument("--prep-auth-handle",type=int,required=True)
        ap.add_argument("--prep-worker-id",required=True)
        ap.add_argument("--prep-heartbeat",type=float,required=True)
        args=ap.parse_args()
        require(sys.argv[0]=="-","INLINE_STDIN_SOURCE_REQUIRED")
        require(os.name=="nt","WINDOWS_REQUIRED")
        return prep_worker_main(args.prep_pipe,args.prep_auth_handle,args.prep_worker_id,args.prep_heartbeat)

    # Preserve the previously homologated external fail-closed order exactly: a
    # not-yet-released candidate blocks before argument parsing or any runtime I/O.
    require(IMPLEMENTATION_READY, IMPLEMENTATION_BLOCKER)
    ap=argparse.ArgumentParser(description="Authenticated stdin-only publisher recovery; no direct production CLI")
    ap.add_argument("--bootstrap-handle",type=int,required=True)
    args=ap.parse_args()
    require(sys.argv[0]=="-","INLINE_STDIN_SOURCE_REQUIRED")
    require(os.name=="nt","WINDOWS_REQUIRED")
    import msvcrt
    fd=msvcrt.open_osfhandle(args.bootstrap_handle,os.O_RDONLY|os.O_BINARY)
    with os.fdopen(fd,"rb") as pipe:
        payload=pipe.read(64*1024*1024+1)
    require(len(payload)<=64*1024*1024,"BOOTSTRAP_TOO_LARGE")
    return dispatch_bootstrap(parse(payload))


if __name__=="__main__":
    try:
        raise SystemExit(main())
    except KeyboardInterrupt:
        print("SAFE_STOP=NO\nINTERRUPTED_RECONCILIATION_REQUIRED=YES",flush=True)
        raise SystemExit(130)
    except Exception as exc:
        print("TICKSTORE_PUBLISHER_RECOVERY_V004=BLOCKED\nREASON="+str(exc),flush=True)
        raise SystemExit(2)
